window.AULAS = window.AULAS || {};
window.AULAS["aula-08"] = {"id": "aula-08", "titulo": "Aula 8 - Semiologia do Sistema Osteomioarticular II", "subtitulo": "Eixo axial, pelve, quadril, joelho, tornozelo, pé e marcha", "pdf": "pdf/aula-08.pdf", "fontes": ["Porto, Semiologia Médica (8ª ed.)", "Porto, Exame Clínico (8ª ed.)", "Bickley / Bates, Propedêutica Médica", "Rocco, Semiologia Médica (2ª ed.)"], "resumo": [{"titulo": "1. Método do exame do eixo axial (slides 2 e 9)", "pontos": [{"t": "Quatro passos fixos", "sub": ["Inspecionar: postura, curvaturas, alinhamento e assimetrias.", "Palpar: processos espinhosos, musculatura paravertebral e pontos dolorosos.", "Mobilizar: flexão, extensão, inclinação lateral e rotação.", "Testar: manobras especiais e exame neurológico (força, sensibilidade e reflexos)."]}, {"t": "Como a anamnese e o exame se completam (slide 2)", "sub": ["A anamnese responde: qual é o padrão dos sintomas? Local ou irradiado, mecânico ou inflamatório, agudo ou crônico.", "O exame físico responde: onde, anatomicamente, está a alteração? Estrutura óssea, articular, muscular ou radicular."]}, {"t": "Conclusão metodológica (slide 9)", "sub": ["O exame físico testa uma hipótese gerada pela anamnese. Não é uma lista de epônimos.", "Método antes da manobra: inspecione, palpe e avalie a mobilidade antes de qualquer teste especial.", "Nenhum teste isolado fecha diagnóstico: interprete cada manobra com a história, o exame neurológico e, quando indicado, a imagem.", "Registro preciso: documente a manobra, o resultado (positivo ou negativo, ângulo, lado) e o que não pôde ser testado por dor."]}, {"t": "Exame físico: sequência (slide 36)", "sub": ["Inspeção: postura, contorno, volume, cor, trofismo muscular, deformidades e marcha. Exponha sempre as duas regiões para comparar.", "Palpação: temperatura (dorso dos dedos, comparando os lados), derrame, espessamento sinovial, crepitação e pontos dolorosos (osso ou partes moles).", "Mobilidade: ativa e passiva igualmente limitadas indicam lesão articular; passiva preservada com ativa limitada indicam dor, fraqueza, tendão, músculo ou nervo.", "Força: graduar de 0 a 5. Dor ao movimento resistido sugere lesão tendínea; diferencie paresia verdadeira de inibição por dor.", "Princípios: examine primeiro o lado não acometido; avalie a articulação acima e abaixo da região dolorosa."]}]}, {"titulo": "2. Dor axial: perguntas e sinais de alarme (slide 3)", "pontos": [{"t": "Perguntas obrigatórias", "sub": ["A dor é local (axial) ou irradia para um membro? Até onde, acima ou abaixo do joelho ou do cotovelo?", "Qual a relação com posição, carga e repouso? Melhora deitado ou piora à noite?", "Há parestesias ou perda de força? Em qual território?", "Há rigidez matinal prolongada ou melhora com a atividade (padrão inflamatório)?", "Qual a evolução temporal: aguda, recorrente ou progressiva?"]}, {"t": "Sinais de alarme (red flags)", "sub": ["Trauma significativo, ou trauma leve em idoso ou com osteoporose.", "Febre, imunossupressão, uso de drogas injetáveis: infecção.", "Câncer prévio, perda de peso inexplicada, idade acima de 50 anos com dor nova: neoplasia.", "Dor noturna ou em repouso que não alivia.", "Déficit neurológico progressivo.", "Retenção ou incontinência urinária ou fecal, com anestesia em sela: síndrome da cauda equina (urgência)."]}, {"t": "Manifestações sistêmicas e número de articulações (slide 34)", "sub": ["Número de articulações: monoarticular, oligoarticular ou poliarticular; simetria.", "Sistêmicas: febre, perda de peso, astenia; pele e unhas (psoríase), mucosas e olhos; queixas intestinais e geniturinárias.", "Erro comum: focar só na articulação dolorosa, sem investigar olho vermelho, diarreia, uretrite ou lesões de pele, que definem o diagnóstico."]}, {"t": "Padrão da dor: mecânica, inflamatória e periarticular (slide 35)", "sub": ["Mecânica (articular): piora com uso e carga, melhora com repouso, rigidez matinal ausente ou breve (menos de 30 min); dor ao movimento ativo e passivo.", "Inflamatória (articular): rigidez matinal de 1 hora ou mais; melhora com a atividade e piora com o repouso; calor, edema e às vezes rubor; dor em todo o arco.", "Periarticular (tendão, bursa, entese): dor localizada e pontual; piora ao contrair ou alongar a estrutura; movimento passivo em geral preservado. Com sinais flogísticos locais (tenossinovite, bursite aguda), a dor é focal e piora ao deitar sobre a região."]}]}, {"titulo": "3. Coluna: inspeção, palpação e testes (slides 4 a 9)", "pontos": [{"t": "Inspeção e mobilidade (slide 4)", "sub": ["De pé, com o dorso exposto: por trás, linha C7 ao sulco interglúteo, nível dos ombros, escápulas, cristas ilíacas e pregas glúteas.", "De perfil: lordose cervical, cifose torácica e lordose lombar.", "Palpação de processos espinhosos e musculatura paravertebral; mobilidade ativa em flexão, extensão, inclinação e rotação."]}, {"t": "Adams (slide 4)", "sub": ["Flexão do tronco com joelhos estendidos e braços pendentes; observe por trás.", "Giba costal ou lombar que persiste: escoliose estrutural.", "Curva que se corrige na flexão: escoliose postural."]}, {"t": "Schober (slide 5)", "sub": ["Paciente de pé, joelhos estendidos. Ponto A na linha média, nas covinhas de Vênus (junção lombossacra); ponto B 10 cm acima.", "Flexão anterior máxima sem fletir os joelhos; meça A-B de novo.", "Normal: aumento de 5 cm ou mais (A-B de 15 a 20 cm).", "Aumento menor que 5 cm: limitação da flexão lombar (ex.: espondilite anquilosante).", "Schober modificado: marca extra 5 cm abaixo de A; a distância inicial de 15 cm deve chegar a 20 cm.", "Variação entre fontes: Rocco descreve o Schober e o modificado; Bates e Porto não o descrevem e avaliam a flexão pela retificação da lordose (Bates) ou pela distância dedos-chão (Porto)."]}, {"t": "Spurling (slide 6)", "sub": ["Paciente sentado, musculatura relaxada; examinador atrás.", "Leve extensão cervical com inclinação lateral e rotação para o lado sintomático; compressão axial suave no topo da cabeça.", "Positivo: reprodução de dor ou parestesia irradiada para o membro superior do mesmo lado (trajeto radicular).", "Dor cervical local isolada é inespecífica.", "Não realizar com suspeita de fratura ou instabilidade cervical.", "Especificidade 89 a 100%; sensibilidade 38 a 97% (Bates).", "Variação entre fontes: Bates usa extensão (olhar para o teto); Rocco usa flexão e rotação, com extensão no lugar da flexão no chamado Spurling modificado."]}, {"t": "Lasègue (slide 7)", "sub": ["Decúbito dorsal, membros estendidos e relaxados. Segure o tornozelo e mantenha o joelho estendido.", "Eleve lentamente e registre o ângulo em que surge a dor e até onde ela irradia.", "Positivo: dor irradiada abaixo do joelho, em geral entre 30 e 70 graus. Indica tensão das raízes L4 a S1, sobretudo L5 e S1.", "Não é positivo: dor só na face posterior da coxa (isquiotibiais) ou dor lombar sem irradiação.", "Lasègue cruzado: elevar o membro sadio reproduz a ciatalgia do lado afetado; pouco sensível, muito específico.", "Variação entre fontes: Rocco fala em 30/45 a 70 graus; Porto dá até 60 graus no capítulo de coluna e cerca de 30 graus no capítulo neurológico (no mesmo livro); Bates não fixa ângulo; o consenso desta aula é dor abaixo do joelho entre 30 e 70 graus."]}, {"t": "Bragard (slide 8)", "sub": ["Complemento do Lasègue: sensibiliza a tensão neural sem aumentar a flexão do quadril.", "Eleve até o ângulo doloroso, abaixe 5 a 10 graus até a dor sumir e faça dorsiflexão passiva do pé com o membro elevado.", "Positivo: retorno da dor irradiada, o que mostra componente radicular (neural), e não muscular."]}, {"t": "Exame neurológico das raízes L4, L5 e S1 (slide 11)", "sub": ["L4: sensibilidade da face medial da perna e do maléolo medial; força de dorsiflexão do tornozelo e extensão do joelho; reflexo patelar diminuído.", "L5: sensibilidade da face lateral da perna e do dorso do pé; força de extensão do hálux; marcha nos calcanhares; sem reflexo confiável.", "S1: sensibilidade da borda lateral e da planta do pé e do calcanhar; força de flexão plantar; marcha na ponta dos pés; reflexo aquileu diminuído.", "Variação entre fontes: patelar é L2 a L4 (Bates, Rocco, Porto); aquileu é S1 (Bates, Rocco) ou L5 a S1 (Porto).", "Erros do Porto (Exame Clínico): atribui o patelar ao nervo ciático (correto: nervo femoral) e cita déficit de flexão do pé na raiz L5 (correto: dorsiflexão e extensão do hálux).", "Alerta: diferencie paresia de inibição por dor. Déficit progressivo, retenção urinária ou anestesia em sela são urgência."]}]}, {"titulo": "4. Quadril e sacroilíaca (slides 12 a 16)", "pontos": [{"t": "Patrick, ou FABER (slide 12)", "sub": ["Decúbito dorsal; membro em posição de 4 (flexão, abdução e rotação externa).", "Maléolo lateral sobre a coxa contralateral, logo acima do joelho; uma mão estabiliza a espinha ilíaca; a outra pressiona o joelho em direção à maca.", "Dor inguinal: articulação coxofemoral. Dor posterior, na região sacroilíaca: articulação sacroilíaca.", "Teste de provocação: não define o diagnóstico isoladamente. Registre o local exato da dor e a distância joelho-maca."]}, {"t": "Gaenslen (slide 13)", "sub": ["Decúbito dorsal, com a nádega do lado testado na borda da maca.", "Quadril contralateral em flexão máxima, retificando a lordose; o membro testado pende; pressione a coxa pendente em hiperextensão.", "Positivo: reprodução da dor posterior habitual, na região sacroilíaca. Não comprova sacroiliíte isoladamente.", "Evite em suspeita de fratura ou lesão aguda do quadril, e garanta que o paciente não caia da maca."]}, {"t": "Rotações em 90 graus (slide 14)", "sub": ["Decúbito dorsal, quadril e joelho a 90 graus. Uma mão estabiliza o joelho; a outra conduz o tornozelo.", "Pé levado para fora: rotação interna. Pé levado para dentro: rotação externa.", "A rotação nomeia o movimento da cabeça do fêmur, e não do pé.", "Topografia da dor: inguinal sugere doença intra-articular (rotação interna é a primeira a limitar na artrose); lateral, com trocânter doloroso, sugere periarticular (tendinopatia glútea, bursite); glútea sugere coluna lombar ou sacroilíaca; o quadril pode doer apenas no joelho.", "Variação entre fontes: Rocco cita RI 40 e RE 60 graus; Porto cita RI e RE de 45 graus com o quadril fletido. Compare sempre com o lado oposto."]}, {"t": "Trendelenburg (slide 15)", "sub": ["Paciente de pé; examinador atrás, observando as cristas ilíacas. Apoio unipodal por cerca de 30 segundos; repita do outro lado.", "Normal: pelve nivelada, ou levemente elevada do lado do pé suspenso.", "Positivo: a pelve cai do lado do pé elevado, por fraqueza do glúteo médio do lado apoiado.", "Armadilhas: dor intensa e déficit de equilíbrio atrapalham; inclinar o tronco sobre o lado apoiado pode mascarar a queda.", "Na marcha, o mesmo mecanismo gera a marcha de Trendelenburg."]}, {"t": "Thomas (slide 16)", "sub": ["Decúbito dorsal. O paciente abraça o joelho do lado não testado e o leva ao tórax até retificar a lordose lombar; a mão do examinador sob a lombar confirma.", "Observe a coxa testada, que deve permanecer apoiada na maca.", "Positivo: a coxa testada se eleva da maca, por contratura em flexão do quadril.", "Com a perna pendente na borda da maca, a extensão do joelho sugere encurtamento do reto femoral.", "Sem retificar a lordose, a hiperlordose compensa e esconde a contratura (falso-negativo)."]}]}, {"titulo": "5. Joelho: derrame e referências (slides 17 a 21)", "pontos": [{"t": "Inspeção e palpação (slide 17)", "sub": ["Inspeção de pé e deitado: alinhamento varo ou valgo, aumento de volume, perda das depressões ao lado da patela, atrofia do quadríceps.", "Palpação com o joelho a cerca de 90 graus: interlinhas medial e lateral (o polo inferior da patela fica na altura da interlinha); patela, tendão do quadríceps, ligamento patelar e tuberosidade da tíbia; colaterais; bolsa anserina; fossa poplítea (cisto de Baker).", "Mobilidade normal: flexão de cerca de 135 graus e extensão de 0 graus.", "Trauma agudo: avalie primeiro deformidade, pulsos distais e perfusão, antes das manobras ligamentares. Diferencie dor na interlinha (articular) de dor focal periarticular."]}, {"t": "Sinal da onda (slide 18)", "sub": ["Joelho estendido, quadríceps relaxado. Ordenhe o recesso suprapatelar para baixo; pressione a face medial; percuta ou deslize a face lateral, logo atrás da borda da patela.", "Positivo: onda de líquido que abaula a face medial, entre patela e fêmur.", "Útil em derrames pequenos; em derrames volumosos e tensos pode não aparecer: use o choque patelar.", "Rigor técnico: quadríceps relaxado, observação tangencial da face medial e comparação com o joelho oposto."]}, {"t": "Choque patelar, ou sinal da tecla (slide 19)", "sub": ["Decúbito dorsal, joelho estendido, quadríceps relaxado. Uma mão comprime o recesso suprapatelar; o indicador da outra empurra a patela contra o fêmur, com movimento rápido.", "Positivo: a patela, flutuando no líquido, desce, choca contra o fêmur e retorna. Indica derrame moderado a volumoso.", "Falso-negativo: derrame pequeno (use o sinal da onda), derrame muito tenso ou contração do quadríceps.", "Variação entre fontes: Rocco diz que a patela se move superoinferiormente (impreciso); o movimento correto é anteroposterior, como descreve Bates."]}, {"t": "Lachman (slide 20)", "sub": ["Decúbito dorsal, joelho em leve flexão (cerca de 15 a 30 graus), isquiotibiais relaxados. Estabilize o fêmur distal e trace a tíbia proximal para a frente, com o polegar na interlinha.", "Positivo: translação anterior maior que a do lado oposto, com parada mole. Indica lesão do LCA e é mais sensível que a gaveta anterior.", "Armadilhas: defesa dos isquiotibiais gera falso-negativo; lesão do LCP pode simular Lachman positivo, por isso teste sempre o LCP.", "Variação de ângulo: Bates usa 15 graus com leve rotação externa; StatPearls cita 20 a 30 graus. Rocco e Porto não descrevem o teste."]}, {"t": "Síntese do quadril e joelho (slide 21)", "sub": ["Sacroilíaca: Patrick (FABER) e Gaenslen; reprodução da dor posterior habitual.", "Coxofemoral: rotação interna em 90/90, FABER e Thomas; dor inguinal e limitação da rotação interna; coxa que se eleva no Thomas indica contratura em flexão.", "Abdutores e região trocantérica: Trendelenburg e palpação do trocânter maior; queda da pelve do lado não apoiado e dor lateral.", "Derrame: sinal da onda (pequeno) e choque patelar (moderado a volumoso).", "LCA: Lachman e gaveta anterior, com translação anterior aumentada e parada mole em relação ao lado oposto."]}, {"t": "Trauma e roteiro do joelho (slide 40)", "sub": ["Roteiro: alinhamento varo ou valgo, contorno, volume, atrofia do quadríceps; interlinhas; polo inferior da patela; face anteromedial da tíbia (bolsa anserina); fossa poplítea.", "Compartimento medial: LCM e bolsa anserina.", "Torção com estalido, derrame volumoso nas primeiras horas (hemartrose), bloqueio mecânico ou instabilidade franca: suspeitar de lesão do LCA, fratura osteocondral ou luxação da patela. Imobilizar e investigar com imagem."]}]}, {"titulo": "6. Joelho: ligamentos, meniscos e tornozelo (slides 22 a 30)", "pontos": [{"t": "Gavetas (slides 23 e 24)", "sub": ["Gaveta anterior, para o LCA: quadril a 45 graus, joelho a 90 graus, pé estabilizado; trace a tíbia para a frente.", "Positivo: deslizamento anterior excessivo, sem ponto final firme, comparado ao lado oposto.", "Antes de tracionar, observe o sinal da queda posterior: se a tíbia já está caída para trás, o deslizamento anterior é só o retorno à posição neutra e é falso-positivo para LCA.", "Gaveta posterior, para o LCP: mesma posição; empurre a tíbia proximal para trás. Positivo: deslocamento posterior excessivo, sem ponto final firme.", "Contexto: lesões isoladas do LCP são menos comuns; o mecanismo típico é trauma direto na tíbia proximal com o joelho fletido."]}, {"t": "Estresse em valgo e varo (slides 25 e 26)", "sub": ["Valgo: coxa levemente abduzida; uma mão empurra o joelho para medial e a outra puxa o tornozelo para lateral. Positivo: abertura medial sem ponto final firme, ou dor na interlinha medial, indica LCM.", "Varo: mesmo teste com as mãos invertidas. Positivo: abertura lateral excessiva, indica LCL (menos comum).", "Teste em extensão completa e em leve flexão de 20 a 30 graus.", "Abertura também em extensão completa sugere lesão associada (cruzados ou cápsula posterior).", "Dor medial sem abertura não é frouxidão. Não confunda alinhamento estático (genu varo) com a abertura provocada pela manobra.", "Variação de ângulo: Bates fala em joelho discretamente fletido, mas os 30 graus do texto referem-se à abdução da coxa; Rocco não cita ângulo; a literatura ortopédica usa 20 a 30 graus, sem consenso (Aronson et al., 2008)."]}, {"t": "McMurray (slide 27)", "sub": ["Decúbito dorsal; segure o calcanhar e leve o joelho à flexão máxima; a outra mão palpa as interlinhas.", "Menisco medial: rotação externa da perna com estresse em valgo, estendendo lentamente.", "Menisco lateral: rotação interna (estresse em varo), estendendo lentamente.", "Positivo: estalido palpável na interlinha, com dor, durante a extensão.", "Estalido indolor isolado é inespecífico. Não force joelho agudamente doloroso ou bloqueado.", "Variação entre fontes: Bates diz que o menisco lateral é só rotação interna; Rocco e Porto não descrevem o teste."]}, {"t": "Apley (slide 28)", "sub": ["Decúbito ventral, joelho a 90 graus, coxa estabilizada contra a maca.", "Compressão: carga axial sobre a planta do pé, com rotação da tíbia. Dor ou estalido na rotação externa indica menisco medial; na rotação interna, menisco lateral.", "Distração: tração da perna para cima e repetição das rotações. Dor na rotação externa indica LCM; na rotação interna, LCL.", "Variação entre fontes: Rocco descreve compressão e tração. O nome 'Apley' aparece no Bates para o teste de coçar do ombro: não confundir.", "Nenhum livro traz figura; as ilustrações são de domínio público (Wikimedia)."]}, {"t": "Síntese do joelho (slide 29)", "sub": ["Há líquido intra-articular? Sinal da onda e choque patelar.", "Estabilidade anteroposterior? Lachman, gaveta anterior e gaveta posterior.", "Estabilidade medial ou lateral? Estresse em valgo (LCM) e em varo (LCL).", "Lesão meniscal? McMurray e compressão de Apley.", "Caso-flash: entorse com pé fixo, estalido audível e derrame volumoso em poucas horas (hemartrose). Hipótese principal: LCA. Teste de escolha: Lachman.", "Bloqueio: impossibilidade mecânica de estender o joelho (fragmento meniscal). Falseio: sensação de o joelho sair do lugar ou perder sustentação."]}, {"t": "Tornozelo: inspeção, mobilidade e força (slides 30 e 31)", "sub": ["Inspeção: edema, equimose, deformidade; alinhamento do retropé com carga, visto por trás.", "Palpação: maléolos (borda posterior e ponta), interlinha tibiotalar anterior, ligamento talofibular anterior e deltóideo, tendão do calcâneo, base do quinto metatarso e navicular.", "Mobilidade: tibiotalar (dorsiflexão e flexão plantar); subtalar (inversão e eversão, com a tíbia estabilizada).", "Força: dorsiflexão (tibial anterior, L4 a L5), flexão plantar (tríceps sural, S1), inversão (tibial posterior) e eversão (fibulares). Gradue de 0 a 5.", "Dor aguda inibe o esforço e simula paresia; fraqueza indolor sugere causa neurológica.", "Variação entre fontes na amplitude normal: Bates (dorsiflexão 20, flexão plantar 50, inversão 35, eversão 25); Rocco (15 a 25, 40 a 50, 30, 20); Porto (0 a 45 para dorsiflexão e flexão plantar, 0 a 20 para inversão, 0 a 40 para eversão)."]}, {"t": "Thompson (slide 32)", "sub": ["Decúbito ventral, com pés pendentes para fora da maca, ou com joelho a 90 graus (ou ajoelhado em uma cadeira).", "Comprima o ventre do tríceps sural e compare com o lado oposto.", "Normal: flexão plantar passiva do pé. Positivo: ausência de flexão plantar, sugere ruptura completa do tendão do calcâneo.", "Flexão plantar ativa preservada (flexores longos, tibial posterior) e capacidade de andar não afastam ruptura. Palpe a falha (gap).", "Sinônimos: Simmonds e Thompson-Doherty. Erro do Rocco: descreve em decúbito dorsal; o correto é decúbito ventral ou ajoelhado."]}, {"t": "Cuidados e uso das manobras (slides 28 e 29)", "sub": ["Apley: evite força excessiva em joelho agudamente traumatizado.", "Síntese do joelho: cada manobra responde a uma pergunta gerada pela história; evite aplicar testes como bateria sem contexto.", "Thompson: o Bates descreve o teste sem citar o epônimo; Rocco e Bates usam os sinônimos Simmonds e Thompson-Doherty."]}]}, {"titulo": "7. Tornozelo e pé: Ottawa, pé e marcha (slides 41 a 43)", "pontos": [{"t": "Regras de Ottawa (slide 41)", "sub": ["Tornozelo: radiografia se houver dor na região maleolar com dor à palpação da borda posterior ou da ponta de um maléolo (6 cm distais), ou incapacidade de dar 4 passos logo após o trauma e no exame.", "Pé: dor no mediopé com dor à palpação da base do quinto metatarso ou do navicular, ou incapacidade de dar 4 passos.", "Edema com cacifo não é sinônimo de derrame articular."]}, {"t": "Pé: apoio, arcos e antepé (slide 42)", "sub": ["Com e sem carga: arco longitudinal medial, arco transverso e calosidades (pontos de hiperpressão).", "Deformidades: pé plano (arco medial reduzido); pé cavo (arco acentuado); hálux valgo (desvio lateral do hálux com proeminência medial da cabeça do primeiro metatarso); dedos em martelo.", "Palpe as cabeças dos metatarsos e as metatarsofalângicas, a fáscia plantar (inserção no calcâneo) e a inserção do tendão do calcâneo.", "Dor entre o terceiro e o quarto metatarsos, com parestesia, sugere neuroma de Morton.", "Compressão lateral do antepé (squeeze): dor na linha das metatarsofalângicas é triagem de sinovite (ex.: AR), não é diagnóstico."]}, {"t": "Marcha (slide 43)", "sub": ["Observe entrada, retorno, mudança de direção e base de apoio (5 a 10 cm).", "Fases: apoio (cerca de 60% do ciclo) e balanço (cerca de 40%). Compare tempo de apoio e comprimento dos passos.", "Marcha antálgica: encurta a fase de apoio do membro doloroso.", "Compensações: queda da pelve do lado em balanço (Trendelenburg) ou inclinação do tronco sobre o membro apoiado (fraqueza abdutora ou dor no quadril)."]}, {"t": "Marcha: padrões e observação (slides 39 e 43)", "sub": ["Ceifante: membro superior fletido e aduzido; membro inferior avança em semicírculo (circundução).", "Parkinsoniana: giro em bloco, com tronco fletido e passos arrastados.", "Marcha antálgica: o passo do lado sadio fica mais curto que o do lado doloroso.", "Fase de apoio: do toque do calcanhar até a saída; compare o tempo de apoio dos dois lados."]}]}, {"titulo": "8. Mãos, marchas patológicas e casos (slides 38 a 39 e 44)", "pontos": [{"t": "Mãos (slide 38)", "sub": ["Inspecione eminências tenar e hipotenar (atrofia sugere lesão do nervo mediano ou ulnar), alinhamento, deformidades, pele e unhas.", "Palpe punhos, MCF, IFP e IFD. Diferencie edema subcutâneo difuso de espessamento sinovial localizado.", "Heberden (IFD): nódulos ósseos duros, sugerem osteoartrite. Bouchard (IFP): nódulos ósseos, sugerem osteoartrite.", "IFP com tumefação fusiforme amolecida: sinovite. MCF e punhos com espessamento amolecido e doloroso: artrite inflamatória (ex.: AR). Em geral poupados na osteoartrite.", "Osteoartrite da mão: Bates, tabela 23.7, com MCF e IFP como padrão da AR e IFD e IFP na osteoartrite."]}, {"t": "Marchas patológicas (slide 39)", "sub": ["Ceifante ou hemiparética (ex.: AVC): membro superior fletido e aduzido; membro inferior estendido, pé em flexão plantar e inversão, circundução.", "Parkinsoniana: tronco fletido, passos curtos e arrastados, pouco balanço dos braços, festinação possível.", "Escarvante ou de pé caído, por fraqueza dos dorsiflexores (miopática e neuropática): eleva o joelho e o antepé toca o chão antes do calcanhar. Ex.: lesão fibular, polineuropatia, radiculopatia L5.", "Anserina: fraqueza bilateral da cintura pélvica (glúteo médio), com oscilação da pelve e do tronco e hiperlordose. Ex.: miopatias. Unilateral: marcha de Trendelenburg."]}, {"t": "Caso integrador: AR crônica (slide 44)", "sub": ["Paciente de 36 anos, com dor e rigidez matinal de 90 minutos nas mãos há 3 meses.", "Inspeção: tumefação simétrica de punhos, MCF e IFP. Palpação: sinovite amolecida e dolorosa em MCF e IFP; IFD poupadas; compressão das MCF dolorosa.", "Raciocínio: poliartrite periférica, simétrica, de pequenas articulações, inflamatória (rigidez maior que 1 hora) e crônica (mais de 6 semanas). Hipótese principal: artrite reumatoide.", "Investigação: VHS e PCR, fator reumatoide e anti-CCP; radiografias de mãos e pés; avaliar manifestações extra-articulares."]}]}, {"titulo": "9. Exames de imagem, urgências e registro (slides 37, 45 a 49)", "pontos": [{"t": "Exames de imagem (slide 37)", "sub": ["Radiografia: primeira linha, para osso, alinhamento, espaço articular, erosões e calcificações. Pelo menos duas incidências ortogonais.", "Ultrassonografia: dinâmica, sem radiação e à beira do leito; avalia derrame, sinovite, tendões, bursas e partes moles superficiais; guia punções; depende do operador.", "TC: detalhe ósseo e fraturas complexas.", "RM: método de escolha para partes moles profundas, ligamentos, meniscos, cartilagem e edema da medula óssea (lesões ocultas à radiografia).", "Erro comum: solicitar imagem antes de formular uma hipótese anatômica pelo exame físico."]}, {"t": "Monoartrite aguda, trauma e coluna (slide 45)", "sub": ["Monoartrite aguda quente, edemaciada e muito dolorosa, de instalação em horas a dias, com ou sem febre: artrite séptica até prova em contrário. Faça artrocentese (Gram, cultura, celularidade e cristais).", "Trauma grave: deformidade, crepitação, ferida próxima à fratura (fratura exposta) ou alteração neurovascular distal: imobilizar e encaminhar com urgência.", "Coluna: dor axial com febre, imunossupressão ou câncer prévio (infecção, metástase); déficit motor progressivo; retenção urinária, incontinência e anestesia em sela (cauda equina): RM e avaliação cirúrgica de urgência."]}, {"t": "Registro e checklist (slide 46)", "sub": ["Região exata e lateralidade.", "Inspeção: deformidade, aumento de volume, cor e trofismo.", "Palpação: calor, derrame e pontos dolorosos.", "Amplitude ativa e passiva, em graus, comparada ao lado oposto.", "Força graduada de 0 a 5. Diferencie paresia verdadeira de limitação por dor.", "Manobra executada, resultado e localização do sintoma provocado.", "Exame neurovascular distal (pulsos, perfusão, sensibilidade e motricidade).", "Exemplo: joelho D com derrame moderado (choque patelar positivo), sem calor; Lachman positivo com parada mole."]}, {"t": "Erros dos livros-texto e divergências (slides 47 e 48)", "sub": ["Rocco: Thompson descrito em decúbito dorsal (correto: ventral); sinal da tecla descrito como superoinferior (correto: anteroposterior).", "Porto (Exame Clínico): patelar atribuído ao nervo ciático (correto: femoral); déficit de flexão do pé na L5 (correto: dorsiflexão e extensão do hálux).", "Porto e Bates: reflexo aquileu em S1 ou L5 a S1 (ver seção de raízes).", "Adotados nesta aula: Lasègue entre 30 e 70 graus; Lachman a 15 a 30 graus; valgo e varo em extensão e em 20 a 30 graus; patelar L2 a L4; aquileu S1."]}, {"t": "Erro adicional do Porto (slide 47)", "sub": ["Porto, Semiologia Médica: 'patelar e aquileu: integridade de L5 e S1'. Correto: patelar é L2 a L4 (sobretudo L4); aquileu é S1; L5 não tem reflexo confiável."]}]}, {"titulo": "10. Síntese: do sintoma ao padrão semiológico (slide 49)", "pontos": [{"t": "Estrutura, manobras e achado", "sub": ["Caracterize o tempo de evolução, o número de articulações e a limitação funcional.", "Localize a provável estrutura: articular, periarticular ou neural.", "Compare o movimento ativo, o passivo e o contra resistência.", "Selecione as manobras específicas pela hipótese, e não como bateria.", "Padrão periarticular: dor focal ao contrair ou alongar tendão ou bursa; arco passivo preservado.", "Padrão articular inflamatório: dor e limitação ativa e passiva, sinais flogísticos e rigidez matinal prolongada.", "Sinais de urgência: infecção articular, trauma grave, déficit progressivo, síndrome da cauda equina."]}]}], "glossario": [{"termo": "Teste de Adams", "epônimo": "Adams", "tecnica": "Flexão anterior do tronco", "definicao": "Giba que persiste = escoliose estrutural. Que se corrige = postural.", "slide": 4}, {"termo": "Teste de Schober", "epônimo": "Schober", "tecnica": "Mensuração A-B com flexão lombar máxima", "definicao": "Normal: aumento de 5 cm. Aumento menor que 5 cm = limitação. Schober modificado: marca 5 cm abaixo de A.", "slide": 5}, {"termo": "Teste de Spurling", "epônimo": "Spurling", "tecnica": "Inclinação lateral + extensão + compressão axial da cabeça", "definicao": "Reprodução de dor irradiada para o membro superior do mesmo lado.", "slide": 6}, {"termo": "Manobra de Lasègue (elevação do membro estendido)", "epônimo": "Lasègue", "tecnica": "Elevação do membro estendido em decúbito dorsal (SLR)", "definicao": "Dor irradiada abaixo do joelho entre cerca de 30° e 70°. Tensão radicular L4-S1.", "slide": 7}, {"termo": "Lasègue cruzado", "epônimo": "Lasègue", "tecnica": "Elevação do membro sadio", "definicao": "Reproduz a ciatalgia do lado afetado. Pouco sensível, muito específico.", "slide": 7}, {"termo": "Manobra de Bragard", "epônimo": "Bragard", "tecnica": "Lasègue + abaixar 5-10° + dorsiflexão passiva do pé", "definicao": "Retorno da dor irradiada confirma tensão neural (radicular).", "slide": 8}, {"termo": "Teste de Patrick (FABER)", "epônimo": "Patrick", "tecnica": "Membro em 4: flexão, abdução e rotação externa", "definicao": "Dor inguinal = coxofemoral; dor posterior = sacroilíaca. Teste de provocação.", "slide": 12}, {"termo": "Teste de Gaenslen", "epônimo": "Gaenslen", "tecnica": "Decúbito dorsal na borda da maca, flexão de um quadril e hiperextensão do outro", "definicao": "Reproduz a dor sacroilíaca habitual. Não é isoladamente diagnóstico.", "slide": 13}, {"termo": "Teste de Trendelenburg", "epônimo": "Trendelenburg", "tecnica": "Apoio unipodal por cerca de 30 s", "definicao": "Queda da pelve do lado do pé elevado = fraqueza dos abdutores do lado apoiado. Marcha de Trendelenburg na marcha.", "slide": 15}, {"termo": "Teste de Thomas", "epônimo": "Thomas", "tecnica": "Flexão do quadril oposto até retificar a lordose lombar", "definicao": "Coxa testada se eleva = contratura em flexão do quadril. Falso-negativo se a lordose não for retificada.", "slide": 16}, {"termo": "Cisto de Baker", "epônimo": "Baker", "tecnica": "Palpação da fossa poplítea", "definicao": "Cisto poplíteo, geralmente associado a derrame ou lesão meniscal.", "slide": 17}, {"termo": "Teste de Lachman", "epônimo": "Lachman", "tecnica": "Joelho a 15-30°, fêmur fixo, tíbia tracionada para frente", "definicao": "Teste de escolha para lesão do LCA. Translação anterior aumentada com parada mole.", "slide": 20}, {"termo": "Teste de McMurray", "epônimo": "McMurray", "tecnica": "Flexão máxima + rotação com extensão lenta", "definicao": "Estalido palpável com dor. Menisco medial: RE + valgo; lateral: RI + varo.", "slide": 27}, {"termo": "Teste de Apley", "epônimo": "Apley", "tecnica": "Decúbito ventral, joelho a 90°: compressão + rotação; distração", "definicao": "Compressão = meniscos. Distração = colaterais.", "slide": 28}, {"termo": "Teste de Thompson", "epônimo": "Thompson", "tecnica": "Decúbito ventral, joelho e tornozelo a 90°, comprimir o tríceps sural", "definicao": "Sem flexão plantar = ruptura do tendão calcâneo. Sinônimos: Simmonds, Thompson-Doherty.", "slide": 32}, {"termo": "Nódulo de Heberden", "epônimo": "Heberden", "tecnica": "Palpação da IFD", "definicao": "Nódulo ósseo duro em IFD: osteoartrite.", "slide": 38}, {"termo": "Nódulo de Bouchard", "epônimo": "Bouchard", "tecnica": "Palpação da IFP", "definicao": "Nódulo ósseo em IFP: osteoartrite.", "slide": 38}, {"termo": "Neuroma de Morton", "epônimo": "Morton", "tecnica": "Palpação entre o 3º e o 4º metatarsos", "definicao": "Dor com parestesia dos dedos.", "slide": 42}], "caso": {"titulo": "Caso integrador: lombociatalgia com déficit de L5", "perfil": "Sr. Raimundo, 52 anos, pedreiro, destro. Sem comorbidades conhecidas. Ex-tabagista. Usa anti-inflamatório ao necessário.", "etapas": [{"titulo": "Etapa 1 · Queixa principal e padrão", "texto": "Sr. Raimundo, 52 anos, pedreiro, procura atendimento por dor na região lombar e na perna direita. Diz: 'a dor desce pela perna até o pé'.", "perguntas": [{"pergunta": "Qual é o padrão de dor inicial mais coerente com a queixa?", "alternativas": ["Dor lombar com irradiação segmentar, na distribuição de uma raiz", "Dor lombar mecânica isolada, sem componente radicular nem irradiação", "Dor neuropática difusa em meia e luva, sugerindo polineuropatia", "Dor inflamatória, com rigidez matinal longa e melhora com atividade", "Dor miofascial referida do glúteo, sem envolvimento de raízes"], "gabarito": "A", "justificativa": "A irradiação segue um trajeto de raiz (da lombar até o pé), o que caracteriza componente radicular. A dor também tem origem axial, na coluna lombar. Padrão axial e radicular associados é a leitura correta nesta etapa.", "erradas": {"B": "A irradiação até o pé não é referida: segue um trajeto de dermátomo, que é radicular.", "C": "Polineuropatia costuma ser simétrica e distal; aqui a dor é unilateral e segue uma raiz.", "D": "Dor inflamatória tem rigidez matinal maior que 1 hora e melhora com atividade; o relato não traz isso.", "E": "Dor miofascial não desce até o pé nem se associa ao trajeto de uma raiz."}}]}, {"titulo": "Etapa 2 · História cronológica", "texto": "Há 6 semanas, ao levantar um saco de cimento, sentiu fisgada na lombar. Nos dias seguintes, a dor passou a descer pela face posterolateral da coxa direita e depois pela perna até o dorso do pé. Piora ao sentar por longo tempo e ao tossir; melhora um pouco deitado. Há 3 semanas, relata formigamento no dorso do pé. Rigidez matinal inferior a 30 minutos.", "perguntas": [{"pergunta": "Qual sequência cronológica é mais coerente com uma hérnia discal lombar?", "alternativas": ["Ciatalgia primeiro, lombalgia depois e parestesia, sem gatilho", "Lombalgia após esforço, depois ciatalgia e parestesia no pé", "Parestesia no dorso do pé, depois lombalgia e dor na nádega", "Dor na coxa após queda, seguida de lombalgia crônica progressiva", "Lombalgia há anos, com piora abrupta da ciatalgia sem gatilho"], "gabarito": "B", "justificativa": "O gatilho mecânico vem primeiro, depois a dor segue o trajeto da raiz de proximal para distal, e a parestesia surge por último. Essa ordem é a típica de compressão radicular progressiva por hérnia.", "erradas": {"A": "Ciatalgia sem lombalgia prévia e sem gatilho é atípica e não segue a ordem de compressão.", "C": "Parestesia distal antes da dor axial não segue a cronologia de uma compressão radicular.", "D": "Dor anterior da coxa após queda aponta para outra estrutura, e não para o trajeto L5.", "E": "Piora abrupta sem gatilho e após anos de lombalgia não corresponde a este relato."}}, {"pergunta": "Qual significado clínico tem a evolução de 6 semanas?", "alternativas": ["Dor crônica, que obriga iniciar opioide de longa duração", "Descarta hérnia discal, pois hérnias são sempre agudas", "Caracteriza dor subaguda, com evolução maior que quatro semanas", "Infecção óssea, pela duração sem melhora espontânea completa", "Neoplasia, pela evolução acima de quatro semanas em maiores de 50"], "gabarito": "C", "justificativa": "Dor de 4 a 12 semanas é subaguda pela definição da ACP 2017. Ela não é crônica e não exige opioide. Também não é, por si só, sinal de infecção ou neoplasia: o que muda a conduta são os red flags.", "erradas": {"A": "Dor crônica começa após 12 semanas, e opioide não é indicado de rotina (ACP 2017; NICE NG59).", "B": "Hérnias podem evoluir por semanas, com dor e déficit que variam; a duração não as descarta.", "D": "Infecção óssea se associa a febre, dor noturna e imunossupressão; nada disso está no relato.", "E": "Idade acima de 50 anos não basta para suspeitar de neoplasia: é preciso um red flag associado."}}]}, {"titulo": "Etapa 3 · Anamnese dirigida e red flags", "texto": "Nega febre, perda de peso, câncer prévio, uso de drogas injetáveis e trauma recente. Dor noturna em repouso que não alivia: nega. Nega alteração urinária, incontinência intestinal ou alteração de sensibilidade na região de sela. Relata que a força da perna direita 'está um pouco pior' nas últimas semanas.", "perguntas": [{"pergunta": "Qual pergunta da anamnese é a mais importante antes de aceitar o padrão mecânico?", "alternativas": ["Em qual horário o paciente costuma fazer a caminhada diária, e por quanto tempo ela dura", "O paciente já fez fisioterapia em outro serviço, e quantas sessões foram realizadas", "Qual foi a marca do analgésico usado nas últimas semanas e se o paciente gostou dele", "Há febre, perda de peso, dor noturna ou déficit motor que esteja piorando com o tempo", "O paciente pratica algum esporte de contato de forma regular ou ocasional no fim de semana"], "gabarito": "D", "justificativa": "Os sinais de alarme (febre, perda de peso, dor noturna e déficit progressivo) definem se o padrão mecânico é seguro. As outras perguntas são úteis, mas não mudam a classificação de risco.", "erradas": {"A": "Horário de caminhada não altera a classificação de risco da dor.", "C": "Marca do analgésico importa para a conduta, mas não para excluir gravidade.", "B": "Tratamentos prévios importam para o histórico, mas não definem red flag.", "E": "Prática esportiva é fator de risco mecânico, e não sinal de alarme."}}, {"pergunta": "Diante do relato 'a força da perna piorou nas últimas semanas', a conduta mais adequada é:", "alternativas": ["Encaminhar para cirurgia de descompressão, sem nova avaliação clínica nem exame de imagem", "Ignorar, pois a fraqueza relatada pelo paciente costuma ser subjetiva e não tem valor clínico", "Iniciar corticoide oral imediatamente, sem realizar exame físico para avaliar a força", "Solicitar eletroneuromiografia antes de qualquer outra avaliação, para classificar a lesão", "Tratar como sinal de alarme e confirmar com exame de força graduado, com seguimento seriado"], "gabarito": "E", "justificativa": "Piora do déficit é sinal de alarme. A primeira coisa é medir a força (escala de 0 a 5) e comparar com o lado oposto. Depois, decidir o seguimento e a urgência. Exame complementar vem depois do exame clínico.", "erradas": {"B": "Relato subjetivo deve ser verificado com exame, e não descartado.", "C": "Corticoide oral não é conduta de rotina nesta situação, e sem exame não há base.", "D": "EMG não é o primeiro exame; o exame clínico e a RM são prioritários.", "A": "Cirurgia sem reavaliação não é conduta adequada sem confirmar o déficit."}}]}, {"titulo": "Etapa 4 · Antecedentes e fatores de risco", "texto": "Antecedentes: ex-tabagista; sem cirurgias de coluna; sem lombalgia prévia relevante. Ocupação: pedreiro, com levantamento repetido de carga. Usa anti-inflamatório ao necessário, com alívio parcial.", "perguntas": [{"pergunta": "Qual fator de risco é o mais relevante para degeneração discal neste paciente?", "alternativas": ["Ser ex-tabagista e levantar carga repetidamente como pedreiro", "Usar anti-inflamatório sem orientação, por tempo indefinido", "Não ter comorbidades e manter o peso estável nos últimos anos", "Ter lombalgia há 20 anos, sem irradiação e com resolução completa", "Trabalhar sentado em escritório, com cadeira ergonômica e pausas"], "gabarito": "A", "justificativa": "Levantamento repetido de carga e tabagismo são fatores de risco mecânico e biológico para degeneração discal. O anti-inflamatório não causa hérnia, e a ausência de comorbidades não protege da degeneração.", "erradas": {"B": "AINE não causa degeneração discal; o risco é gastrointestinal e renal, não estrutural.", "C": "Ausência de comorbidades não elimina o risco de degeneração por carga e tabagismo.", "D": "Lombalgia prévia resolvida não é fator de risco ativo para hérnia nova.", "E": "Trabalho sentado com boa ergonomia reduz o risco, e não o aumenta."}}]}, {"titulo": "Etapa 5 · Inspeção", "texto": "De pé, dorso exposto. Postura antálgica com inclinação do tronco para a esquerda. Contratura da musculatura paravertebral lombar à direita. Sem atrofia visível das pernas. Lordose lombar preservada no perfil. Na marcha, o apoio do lado direito fica mais curto.", "perguntas": [{"pergunta": "O que a inclinação do tronco para a esquerda sugere?", "alternativas": ["Escoliose estrutural, com giba costal que não se corrige", "Postura antálgica, de alívio da dor radicular do lado", "Compensação de encurtamento do membro inferior esquerdo", "Hipercifose torácica, associada a dor cervical articular", "Lordose lombar fisiológica acentuada, sem relação com a dor"], "gabarito": "B", "justificativa": "A postura antálgica afasta o tronco da raiz comprimida, o que reduz a tração sobre ela. Por isso a inclinação é para o lado oposto à dor. Escoliose estrutural exigiria giba que persiste na flexão.", "erradas": {"A": "Escoliose estrutural tem giba que persiste na flexão anterior, o que não foi descrito.", "C": "Encurtamento de membro não faria a postura se associar a dor radicular com contratura do lado oposto.", "D": "A dor é lombar e radicular, não cervical; a cifose não explica o achado.", "E": "Lordose preservada no perfil não explica uma inclinação lateral antálgica."}}, {"pergunta": "O encurtamento do apoio do lado direito na marcha é mais compatível com:", "alternativas": ["Marcha de Trendelenburg por fraqueza do glúteo médio do lado direito, com queda da pelve", "Marcha parkinsoniana, com passos curtos, tronco fletido e pouca oscilação dos braços", "Marcha antálgica, com redução do tempo de apoio sobre o membro doloroso do lado direito", "Marcha escarvante por pé caído de dorsiflexores, com elevação exagerada do joelho direito", "Marcha anserina por fraqueza bilateral da cintura pélvica, com oscilação do tronco"], "gabarito": "C", "justificativa": "Na marcha antálgica, o paciente reduz o tempo de apoio do lado doloroso. Trendelenburg aparece como queda da pelve sem dor radicular. O relato de dor irradiada e de contratura torna a marcha antálgica a mais coerente.", "erradas": {"A": "Trendelenburg tem queda da pelve no apoio unipodal; o relato não descreve esse achado.", "B": "Marcha parkinsoniana é bilateral e sem assimetria de apoio como a descrita.", "D": "Pé caído causaria arrasto do antepé, e não encurtamento de apoio por dor.", "E": "Marcha anserina é bilateral; o achado aqui é unilateral e de origem dolorosa."}}]}, {"titulo": "Etapa 6 · Palpação e mobilidade", "texto": "Processos espinhosos de L4-L5 dolorosos à palpação. Contratura paravertebral à direita. Flexão lombar reduzida e dolorosa. Teste de Schober: distância A-B de 3 cm (esperado aumento de 5 cm).", "perguntas": [{"pergunta": "Qual é a interpretação do Schober com aumento de 3 cm?", "alternativas": ["Normalidade, pois o aumento mínimo aceitável para o teste é de 2 centímetros", "Espondilite anquilosante ativa, com rigidez matinal e padrão inflamatório confirmados", "Hipermobilidade lombar, pois o aumento observado supera o esperado para a idade", "Limitação da flexão lombar, pois o aumento esperado é de 5 centímetros", "Hiperlordose compensatória, que sempre mascara a flexão real e invalida o teste"], "gabarito": "D", "justificativa": "O aumento esperado é de 5 cm (A-B passa de 15 para 20 cm). Aumento menor que 5 cm indica limitação da flexão lombar. A limitação, sozinha, não confirma espondilite.", "erradas": {"A": "Aumento de 3 cm está abaixo do mínimo de 5 cm, e não é normal.", "C": "Hipermobilidade seria aumento acima do esperado, e não abaixo.", "B": "Espondilite exige padrão inflamatório e outros achados, que não estão descritos.", "E": "Hiperlordose pode mascarar o teste, mas não o invalida sempre."}}, {"pergunta": "Sobre o Schober, qual afirmação é a mais correta quanto à espondilite anquilosante?", "alternativas": ["Um Schober normal exclui espondilite em qualquer fase da doença", "O Schober mede apenas a flexão cervical, sem relação lombar", "Um Schober limitado confirma espondilite e dispensa outros exames", "O Schober só é válido em decúbito dorsal, nunca em pé", "Um Schober limitado, isolado, não confirma espondilite"], "gabarito": "E", "justificativa": "O Schober é um dos critérios de avaliação, mas não é diagnóstico isolado. Ele é limitado por dor e por contratura, e a espondilite exige padrão inflamatório, dor de costas inflamatória e outros achados (exames de imagem da sacroilíaca).", "erradas": {"A": "Schober normal não exclui espondilite, sobretudo nas fases iniciais.", "C": "Limitação do Schober não substitui a avaliação de sacroilíaca e de padrão inflamatório.", "D": "O Schober é feito em pé, com o paciente de pé e joelhos estendidos.", "B": "O Schober mede a flexão lombar, e não a cervical."}}]}, {"titulo": "Etapa 7 · Manobras de tensão radicular", "texto": "Lasègue direito positivo a 40°, com dor irradiada abaixo do joelho. Lasègue esquerdo negativo. Bragard direito positivo: após abaixar o membro 5 a 10°, a dorsiflexão passiva do pé reproduz a dor irradiada.", "perguntas": [{"pergunta": "Como interpretar o Lasègue direito positivo a 40° com dor abaixo do joelho?", "alternativas": ["Tensão radicular, pois a dor irradia abaixo do joelho entre cerca de 30° e 70° de elevação", "Tensão de isquiotibiais, pois a dor se localiza na face posterior da coxa do lado testado", "Sinal de sacroiliíte, pois a dor é unilateral e surge com a flexão do quadril do paciente", "Artrose coxofemoral, pois a dor se reproduz com a elevação ativa do membro estendido", "Resultado inespecífico, pois apenas o Lasègue cruzado tem valor diagnóstico para radiculopatia"], "gabarito": "A", "justificativa": "A dor irradiada abaixo do joelho, na faixa de 30° a 70°, indica tensão das raízes L4-S1. Dor só na coxa sugere isquiotibiais, e não é Lasègue positivo.", "erradas": {"B": "Dor apenas na face posterior da coxa aponta para isquiotibiais, o que não é o caso descrito.", "C": "Sacroiliíte costuma causar dor glútea, e não irradiação abaixo do joelho pelo trajeto radicular.", "D": "Artrose coxofemoral causa dor inguinal e limitação de rotação, o que não foi descrito.", "E": "O Lasègue direto tem valor diagnóstico; o cruzado é apenas mais específico."}}, {"pergunta": "Qual conclusão é mais precisa diante do Bragard positivo?", "alternativas": ["A dor é muscular, pois a dorsiflexão alonga a panturrilha", "A dor é neural, pois a dorsiflexão tensiona a raiz", "A dor é articular, pois envolve a articulação do tornozelo", "A dor é vascular, pois a dorsiflexão reduz o fluxo da perna", "A dor é psicogênica, pois o exame neurológico é normal"], "gabarito": "B", "justificativa": "O Bragard sensibiliza a tensão neural sem aumentar a flexão do quadril. Se a dor volta com a dorsiflexão, o componente é radicular. Isso separa a dor neural da dor de isquiotibiais.", "erradas": {"A": "Dor muscular de isquiotibiais não se reproduz com a dorsiflexão do pé de forma irradiada.", "C": "Tornozelo não é a fonte da dor no Bragard, que é neural.", "D": "Vascular não explica a reprodução da irradiação com a dorsiflexão.", "E": "O exame neurológico é objetivo e a dor radicular tem base anatômica."}}, {"pergunta": "Lasègue esquerdo negativo. Qual é o significado clínico mais útil?", "alternativas": ["Ausência de comprometimento da coluna, pois a dor é lateralizada e não compromete o lado oposto", "Lasègue bilateral negativo excluiria definitivamente a hérnia discal e a radiculopatia associada", "Achado lateralizado, coerente com compressão radicular de um só lado, sem excluir a hérnia", "Ausência de tensão neural, pois o teste depende de dor bilateral simultânea nos dois membros", "Resultado sem valor, pois o Lasègue exige a elevação simultânea dos dois membros inferiores"], "gabarito": "C", "justificativa": "Um Lasègue negativo do lado oposto é compatível com um processo unilateral. Ele não exclui a compressão do lado direito, e um Lasègue bilateral negativo, por outro lado, não exclui hérnia central ou lateral.", "erradas": {"A": "Dor lateralizada não descarta a coluna: é justamente o que a hérnia unilateral faz.", "B": "Lasègue bilateral negativo não exclui hérnia, que pode ser assintomática na elevação.", "D": "O teste não exige dor bilateral; é realizado membro a membro.", "E": "O Lasègue é feito um membro de cada vez, e o resultado unilateral tem valor."}}]}, {"titulo": "Etapa 8 · Quadril e sacroilíaca", "texto": "FABER direito e esquerdo negativos, sem dor inguinal ou posterior reproduzida. Trendelenburg negativo bilateralmente. Rotações passivas do quadril em 90°/90° sem limitação. Gaenslen negativo.", "perguntas": [{"pergunta": "O que os testes de quadril e sacroilíaca negativos afastam, principalmente?", "alternativas": ["Hérnia discal lombar com compressão da raiz L5, que é a causa principal da dor do paciente", "Síndrome da cauda equina com retenção urinária, afastada pelo exame de quadril e sacroilíaca", "Radiculopatia S1 com comprometimento motor do tríceps sural, confirmada pelos testes de quadril", "Artrose coxofemoral e sacroiliíte como causa principal da dor, pelos testes específicos negativos", "Estenose de canal lombar com claudicação neurogênica, afastada pelos testes de quadril do paciente"], "gabarito": "D", "justificativa": "FABER, Gaenslen, Trendelenburg e rotações avaliam quadril e sacroilíaca. Negativos, afastam essas estruturas como causa principal. Eles não tratam da coluna nem da raiz, que são avaliadas em outras etapas.", "erradas": {"A": "Hérnia discal não é avaliada por FABER ou Gaenslen; é a coluna, e não o quadril.", "C": "Radiculopatia S1 é avaliada por aquileu e flexão plantar, e não pelos testes de quadril.", "B": "Cauda equina é avaliada por sela e esfíncter, e não pelos testes de quadril.", "E": "Estenose de canal é avaliada por história de claudicação e exame de coluna, não de quadril."}}, {"pergunta": "Rotações em 90°/90° normais e dor inguinal ausente. Qual conclusão é a mais adequada?", "alternativas": ["Tendinopatia do glúteo máximo, pela rotação externa livre", "Artrose coxofemoral confirmada, pela amplitude preservada", "Dor glútea periarticular do trocânter como única hipótese", "Dor do joelho obrigatoriamente referida do quadril", "Sem sinais de artrose coxofemoral neste exame físico"], "gabarito": "E", "justificativa": "Rotações normais e ausência de dor inguinal reduzem a probabilidade de artrose coxofemoral, mas não a excluem. Um exame negativo não fecha diagnóstico: o raciocínio segue para outras estruturas.", "erradas": {"B": "Ausência de dor inguinal e rotação preservada não confirmam artrose; apenas a tornam menos provável.", "C": "Dor glútea periarticular é uma hipótese, mas não a única, e exige avaliação adicional.", "D": "Dor referida do quadril ao joelho existe, mas não é obrigatória nem é a única possibilidade.", "A": "Rotação externa livre não confirma tendinopatia; é um exame de amplitude, não de tendão."}}]}, {"titulo": "Etapa 9 · Exame neurológico dirigido", "texto": "Força: dorsiflexão do hálux direito 4/5; dorsiflexão do tornozelo 5/5; flexão plantar 5/5; extensão do joelho 5/5. Sensibilidade à pinça reduzida no dorso do pé direito e na face lateral da perna direita. Reflexo patelar presente e simétrico. Reflexo aquileu presente e simétrico. Marcha nos calcanhares com dificuldade à direita.", "perguntas": [{"pergunta": "Qual raiz está comprometida, considerando a força do hálux e a sensibilidade do dorso do pé?", "alternativas": ["L5, pois a extensão do hálux e o dorso do pé dependem dela", "L4, pois há fraqueza do tibial anterior e dorsiflexão alterada", "S1, pois a flexão plantar é a principal função afetada", "L3, pois a fraqueza do hálux é de origem do nervo femoral", "S2, pois a fraqueza é sacral e a sensibilidade segue o pudendo"], "gabarito": "A", "justificativa": "O extensor longo do hálux e o território do dorso do pé e da face lateral da perna são L5. A dorsiflexão do tornozelo (tibial anterior) é L4-L5, o que a torna preservada aqui.", "erradas": {"B": "A fraqueza seria de L4 se o tibial anterior estivesse afetado, o que não é o caso.", "C": "S1 comprometida causaria fraqueza da flexão plantar, que está preservada.", "D": "L3 inerva o quadríceps e a face anterior da coxa, não o hálux nem o dorso do pé.", "E": "S2 não corresponde ao território do hálux nem ao dorso do pé."}}, {"pergunta": "Aquileu presente e simétrico. O que se pode concluir?", "alternativas": ["L5 íntegra, pois o reflexo aquileu depende diretamente da raiz L5 e não da raiz S1", "S1 íntegra, o que reduz a probabilidade de radiculopatia S1 como causa do quadro do paciente", "L4 comprometida, pois o reflexo aquileu depende da raiz L4 quando a perna está fletida", "Compressão medular alta, pois o reflexo aquileu presente indica preservação das vias longas", "Neuropatia periférica generalizada, pois o reflexo aquileu presente não afasta polineuropatia"], "gabarito": "B", "justificativa": "O aquileu é S1 (Bates, Rocco) ou L5-S1 (Porto). Presente e simétrico reduz a chance de radiculopatia S1. Ele não exclui L5, que tem reflexo pouco confiável.", "erradas": {"A": "Aquileu não depende de L5 isoladamente; L5 não tem reflexo confiável.", "C": "O aquileu não depende de L4; o reflexo de L4 é o patelar.", "D": "Compressão medular alta causaria alteração de reflexos em outros níveis e sinais de vias longas.", "E": "Reflexo presente não afasta neuropatia; por isso o exame se faz por território, e não só por reflexo."}}, {"pergunta": "Qual é a principal diferença entre o comprometimento radicular L5 e o do nervo fibular comum?", "alternativas": ["A radiculopatia poupa a extensão do hálux, enquanto o nervo fibular comum a compromete sempre", "Ambas seguem o mesmo padrão de território, por isso não há diferença clínica útil entre elas", "A radiculopatia segue o padrão de dermátomo, e o fibular segue o padrão de nervo periférico", "O nervo fibular comum sempre causa dor lombar associada, o que não ocorre na radiculopatia L5", "A radiculopatia afeta apenas a sensibilidade, enquanto o nervo fibular comum afeta só a força"], "gabarito": "C", "justificativa": "Radiculopatia L5 segue o dermátomo (uma raiz), e o nervo fibular comum segue o território de um nervo periférico, que é diferente. Essa distinção ajuda a localizar a lesão.", "erradas": {"B": "Há diferença clínica útil: dermátomo versus nervo periférico tem padrões distintos.", "A": "Radiculopatia L5 costuma comprometer o hálux; o fibular também, mas por outro mecanismo.", "D": "Lesão do fibular não causa dor lombar; a dor lombar é característica da radiculopatia.", "E": "Ambas podem afetar sensibilidade e força, dependendo da lesão."}}]}, {"titulo": "Etapa 10 · Sela, esfíncter e exame final", "texto": "Sensibilidade em sela e tônus do esfíncter anal: normais. Pulsos pediosos palpáveis e perfusão distal normal.", "perguntas": [{"pergunta": "Por que avaliar sela e esfíncter mesmo sem queixa de bexiga ou intestino?", "alternativas": ["Para medir o tônus anal como parâmetro da força lombar", "Para confirmar a hérnia, pois sela alterada é sempre diagnóstica", "Para avaliar o risco de hérnia umbilical associada ao esforço", "Para descartar a síndrome da cauda equina, urgência cirúrgica", "Para classificar a dor como neuropática, pela sensibilidade sacral"], "gabarito": "D", "justificativa": "A cauda equina pode começar com alteração discreta de sela ou de esfíncter, antes de a queixa aparecer. Por isso o exame é obrigatório em lombalgia com irradiação.", "erradas": {"B": "Alteração de sela não é sempre diagnóstica de hérnia; é sinal de urgência a investigar.", "C": "Hérnia umbilical não se relaciona com sela ou esfíncter nem com esta avaliação.", "A": "Tônus anal não mede a força lombar e não substitui a avaliação neurológica.", "E": "Alteração sacral pode ocorrer em cauda equina, mas o exame serve para descartá-la."}}]}, {"titulo": "Etapa 11 · Exames complementares", "texto": "Radiografia lombar (AP e perfil): sem fratura; discreta redução do espaço discal L4-L5. Ressonância magnética lombar: hérnia discal posterolateral à direita em L4-L5, comprimindo a raiz L5 direita.", "perguntas": [{"pergunta": "Por que a radiografia isolada não basta neste caso?", "alternativas": ["Radiografia exige contraste intravenoso para avaliar raízes nervosas, o que o paciente não aceita", "Radiografia mostra o disco com precisão, mas não consegue mostrar a raiz nervosa comprimida", "Radiografia é contraindicada em dor lombar aguda com irradiação, por causa da dose de radiação", "Radiografia só mostra fraturas, e a hérnia já foi confirmada clinicamente pelo exame de Lasègue", "Radiografia não mostra partes moles, como disco e raiz, e a RM é o método de escolha para hérnia"], "gabarito": "E", "justificativa": "Radiografia avalia osso e alinhamento, e não partes moles. A RM mostra o disco, a raiz e a compressão, e é o método de escolha para hérnia com radiculopatia.", "erradas": {"B": "Radiografia mostra o disco de forma indireta (espaço discal), mas não mostra a raiz nem a hérnia.", "C": "Radiografia não é contraindicada na lombalgia; ela é o primeiro exame ósseo.", "D": "Hérnia não se confirma pelo Lasègue; ele orienta a hipótese, e a imagem a confirma.", "A": "RM não exige contraste intravenoso para avaliar hérnia e raiz."}}, {"pergunta": "A RM mostra hérnia L4-L5 posterolateral à direita. Qual é a correlação com o quadro?", "alternativas": ["Hérnia L4-L5 posterolateral comprime a raiz L5 no forame", "Hérnia L4-L5 comprime a raiz L4, explicando o déficit do hálux", "Hérnia central em L5-S1 explica o déficit, mas não a irradiação", "Hérnia lateral em L3-L4 comprime a raiz femoral, sem relação", "Hérnia L4-L5 explica fraqueza bilateral do hálux, por ser central"], "gabarito": "A", "justificativa": "A hérnia posterolateral L4-L5 à direita comprime a raiz L5 que sai pelo forame. O déficit de hálux e o território do dorso do pé são L5, o que dá correlação clínico-radiológica.", "erradas": {"B": "Raiz L4 não inerva o extensor do hálux; o déficit seria de L5.", "C": "Hérnia central L5-S1 comprime S1 ou a cauda, e não o déficit de L5 descrito.", "D": "Hérnia L3-L4 comprime L4 ou L3, sem relação com o hálux.", "E": "Hérnia central tende a causar sintomas bilaterais; o achado é unilateral."}}]}, {"titulo": "Etapa 12 · Hipóteses diagnósticas", "texto": "Reunindo os achados: dor mecânica com irradiação; postura antálgica; Lasègue e Bragard positivos do lado direito a 40°; déficit de L5 com reflexos preservados; RM com hérnia L4-L5 à direita comprimindo L5.", "perguntas": [{"pergunta": "Qual é a hipótese diagnóstica principal?", "alternativas": ["Radiculopatia S1 direita por hérnia L5-S1 central, com reflexo aquileu comprometido", "Radiculopatia L5 direita por hérnia discal L4-L5 posterolateral, confirmada pela RM", "Estenose de canal lombar com claudicação neurogênica bilateral e déficit simétrico", "Sacroiliíte direita com irradiação para o membro inferior e teste de FABER positivo", "Espondilite anquilosante em fase inicial com radiculopatia associada e Schober limitado"], "gabarito": "B", "justificativa": "Reúne o trajeto L5, o déficit de hálux, o reflexo aquileu preservado e a hérnia L4-L5 à direita. As demais hipóteses não explicam ao mesmo tempo o território, o reflexo e a imagem.", "erradas": {"A": "S1 teria aquileu comprometido e fraqueza de flexão plantar, o que não ocorreu.", "C": "Estenose é bilateral e costuma ter claudicação, o que não foi descrito.", "D": "Sacroiliíte não causa déficit de hálux nem alteração de sensibilidade em L5.", "E": "Espondilite não explica o déficit de L5 nem a hérnia confirmada na RM."}}, {"pergunta": "Qual diagnóstico diferencial é mais difícil de afastar apenas com o exame clínico?", "alternativas": ["Pielonefrite, pela lombalgia com febre e alteração urinária", "Neoplasia óssea, pela dor noturna em idosos com perda de peso", "Estenose de canal lombar, de manifestação clínica sutil", "Aneurisma de aorta abdominal, pela dor lombar e pulsos fracos", "Osteomielite vertebral, pela dor lombar com febre e inflamação"], "gabarito": "C", "justificativa": "Estenose e hérnia se sobrepõem em sintomas e exame, e a diferença é feita pela imagem e pela história de claudicação. Os demais têm sinais de alarme ausentes no caso (febre, perda de peso, alteração urinária).", "erradas": {"B": "Dor noturna não está presente no caso; a neoplasia seria afastada pela ausência de red flags.", "A": "Pielonefrite exige febre e alteração urinária, que foram negadas.", "D": "Aneurisma tem dor difusa e pulso alterado; o exame descrito tem perfusão normal.", "E": "Osteomielite exige febre e marcadores de infecção, que não foram descritos."}}]}, {"titulo": "Etapa 13 · Conduta", "texto": "Orientação: evitar carga pesada e manter atividade leve. Analgesia e anti-inflamatório por período curto. Fisioterapia orientada. Reavaliação em 4 a 6 semanas, com exame de força e de sensibilidade.", "perguntas": [{"pergunta": "Qual é a conduta inicial mais adequada?", "alternativas": ["Repouso absoluto por três semanas, para reduzir a pressão no disco", "Cirurgia imediata, dada a irradiação e o déficit do hálux", "Corticoide oral em dose alta por 30 dias, como primeira linha", "Tratamento conservador, com analgesia, orientação e reavaliação", "Infiltração epidural imediata, sem reavaliação, em toda hérnia na RM"], "gabarito": "D", "justificativa": "Sem déficit progressivo, sem cauda equina e com dor mecânica, a conduta inicial é conservadora, com reavaliação estruturada. Cirurgia imediata é reservada a critérios específicos.", "erradas": {"B": "Cirurgia imediata não é indicada sem déficit progressivo ou sinais de cauda equina.", "C": "Corticoide oral de rotina não tem benefício em ciatalgia (NICE NG59).", "A": "Repouso prolongado piora a recuperação; o máximo recomendado é de cerca de dois dias.", "E": "Infiltração epidural não é conduta de rotina sem reavaliação; é indicada caso a caso."}}, {"pergunta": "Na reavaliação, o déficit de força piorou. Qual é a próxima conduta?", "alternativas": ["Manter o tratamento conservador por mais quatro semanas, sem nova avaliação do déficit neurológico", "Trocar apenas o analgésico e aguardar a próxima consulta de rotina em três meses de intervalo", "Repetir a RM após seis meses, antes de qualquer decisão sobre o tratamento do paciente", "Iniciar gabapentinoide e manter repouso relativo, aguardando melhora espontânea do déficit", "Encaminhar para avaliação neurocirúrgica, por déficit motor progressivo como critério de urgência"], "gabarito": "E", "justificativa": "Déficit motor progressivo é critério para encaminhamento neurocirúrgico. Não se espera o prazo do tratamento conservador nesse caso.", "erradas": {"A": "Déficit progressivo não pode esperar mais quatro semanas sem reavaliação.", "B": "Trocar analgésico não trata o déficit progressivo, e três meses é prazo longo demais.", "D": "Gabapentinoide não é indicado para ciatalgia e não reverte déficit.", "C": "A RM já mostra hérnia; repetir após seis meses atrasa a decisão necessária."}}, {"pergunta": "Por que o gabapentinoide não deve ser usado de rotina neste caso?", "alternativas": ["Porque o NICE NG59 não recomenda, e a metanálise de Enke não mostrou benefício frente a placebo", "Porque a dor neuropática sempre exige opioide associado, e o gabapentinoide sozinho não funciona", "Porque causa lesão hepática irreversível em dose terapêutica, o que contraindica o uso ambulatorial", "Porque só é indicado após cirurgia, e nunca antes do tratamento conservador de primeira linha", "Porque piora o déficit motor de forma direta, por bloqueio da condução do impulso nervoso"], "gabarito": "A", "justificativa": "NICE NG59 não recomenda gabapentinoides para ciatalgia. A metanálise de Enke (CMAJ 2018) não mostrou benefício frente a placebo para dor radicular lombar, com mais efeitos adversos.", "erradas": {"B": "Opioide associado não é exigido por gabapentinoide; e não há essa regra para ciatalgia.", "C": "Gabapentinoide não causa lesão hepática irreversível em dose terapêutica.", "D": "Não há indicação pós-cirúrgica específica que justifique o uso de rotina antes do tratamento.", "E": "Gabapentinoide não piora o déficit motor por bloqueio de condução."}}, {"pergunta": "Em que momento deve-se reavaliar o tratamento conservador e considerar encaminhamento se não houver melhora?", "alternativas": ["Após uma semana, pela regra de curto prazo da lombalgia", "Em cerca de quatro a seis semanas, se não melhorar", "Somente após doze meses, quando a dor passa a ser crônica", "No primeiro dia, pois hérnia com irradiação exige cirurgia", "Apenas após a cirurgia, sem reavaliação clínica anterior"], "gabarito": "B", "justificativa": "A reavaliação em quatro a seis semanas é o intervalo usual. Antes disso, em caso de déficit progressivo ou sinal de alarme, o encaminhamento é imediato.", "erradas": {"A": "Uma semana é cedo demais para julgar resposta ao tratamento conservador.", "C": "Doze meses define cronicidade, mas a decisão é tomada muito antes, com reavaliação seriada.", "D": "Hérnia com irradiação não exige cirurgia no primeiro dia sem critérios específicos.", "E": "Acompanhamento pós-cirúrgico não substitui a reavaliação antes da decisão de operar."}}, {"pergunta": "Qual achado tornaria a indicação cirúrgica mais precoce?", "alternativas": ["Dor que melhora com a caminhada e piora em repouso, sem déficit neurológico associado", "Irradiação para a face posterior da coxa, sem déficit motor nem alteração de sensibilidade", "Retenção urinária ou anestesia em sela, como sinais de síndrome da cauda equina", "Dor lombar com rigidez matinal inferior a trinta minutos, sem sinais neurológicos associados", "Lasègue positivo a setenta graus, com exame neurológico completamente normal e sem déficit"], "gabarito": "C", "justificativa": "Retenção urinária e anestesia em sela são síndrome da cauda equina, que é urgência cirúrgica. Os outros achados são dor sem gravidade ou sinais isolados sem déficit.", "erradas": {"A": "Dor que melhora com caminhada é típica de mecânica, sem indicação cirúrgica precoce.", "B": "Irradiação sem déficit é indicação de tratamento conservador.", "D": "Rigidez matinal curta é mecânica e não indica cirurgia.", "E": "Lasègue a 70° sem déficit não é indicação de cirurgia precoce."}}]}]}, "questoes": [{"id": 1, "nivel": "muito_dificil", "enunciado": "No teste de Schober modificado, qual é a distância inicial entre os pontos A e B e o valor mínimo esperado após a flexão?", "alternativas": ["Inicial de 15 cm e final de pelo menos 20 cm", "Inicial de 10 cm e final de 15 cm, com aumento de 5 cm", "Inicial de 20 cm e final de pelo menos 25 cm", "Inicial de 5 cm e final de pelo menos 10 cm", "Inicial de 15 cm e final de pelo menos 16 cm"], "gabarito": "A", "justificativa": "No Schober modificado, a distância inicial de 15 cm deve chegar a pelo menos 20 cm na flexão máxima.", "epônimo": null, "tecnica": "Schober", "slide": 5}, {"id": 2, "nivel": "muito_dificil", "enunciado": "Qual é a contraindicação de segurança antes da manobra de Spurling?", "alternativas": ["Dor cervical crônica sem irradiação para o membro", "Suspeita de fratura ou instabilidade cervical", "Paciente sentado com musculatura cervical tensa", "Tontura leve após a flexão do pescoço em paciente idoso", "Dor cervical com rigidez matinal de quinze minutos"], "gabarito": "B", "justificativa": "Spurling não deve ser realizado com suspeita de fratura ou instabilidade cervical.", "epônimo": null, "tecnica": "Spurling", "slide": 6}, {"id": 3, "nivel": "muito_dificil", "enunciado": "No sinal de Lasègue cruzado, qual é a característica diagnóstica para hérnia lombar?", "alternativas": ["Alta sensibilidade e baixa especificidade, em adultos", "Sensível e específico ao mesmo tempo, na prática", "Muito específico e pouco sensível, na hérnia lombar", "Sensível apenas para radiculopatia cervical, em idosos", "Nem sensível nem específico na prática clínica diária"], "gabarito": "C", "justificativa": "Lasègue cruzado, com elevação do membro sadio reproduzindo a ciatalgia, é muito específico e pouco sensível.", "epônimo": null, "tecnica": "Lasègue", "slide": 7}, {"id": 4, "nivel": "muito_dificil", "enunciado": "Na manobra de Bragard, após a dor irradiada aparecer no Lasègue, qual é o passo seguinte e o achado positivo?", "alternativas": ["Abaixar 5 a 10 graus e fletir o quadril, com dor muscular", "Manter o ângulo e pedir extensão do hálux, com fraqueza", "Elevar mais 10 graus e rotacionar o quadril, com dor inguinal", "Abaixar 5 a 10 graus, dorsiflexão passiva e retorno da dor", "Abaixar o membro e medir a distância dedos-chão, em cm"], "gabarito": "D", "justificativa": "Bragard: abaixar 5 a 10 graus e fazer dorsiflexão passiva; o retorno da dor irradiada indica tensão neural radicular.", "epônimo": null, "tecnica": "Bragard", "slide": 8}, {"id": 5, "nivel": "muito_dificil", "enunciado": "Qual reflexo tendinoso é confiável para avaliar a raiz L5, e qual é a raiz do reflexo patelar?", "alternativas": ["Reflexo patelar para L5; reflexo patelar de L4 e L5", "Reflexo cremastérico para L5; patelar de L2, preservado", "Reflexo aquileu para L5; patelar de S1 com resposta viva", "Reflexo bulbocavernoso para L5; patelar de L5, mantido", "Não há reflexo confiável para L5; patelar de L2 a L4"], "gabarito": "E", "justificativa": "O patelar é L2 a L4 (sobretudo L4), o aquileu é S1, e L5 não tem reflexo confiável.", "epônimo": null, "tecnica": "Reflexos", "slide": 11}, {"id": 6, "nivel": "muito_dificil", "enunciado": "Na fraqueza de dorsiflexão com extensão do hálux reduzida e marcha nos calcanhares alterada, qual raiz é a mais provável?", "alternativas": ["L5, com déficit de dorsiflexão e extensão do hálux", "L4, com fraqueza do tibial anterior e reflexo patelar abolido", "S1, com fraqueza da flexão plantar e aquileu diminuído", "L3, com fraqueza do quadríceps e patelar aumentado", "C6, com fraqueza do extensor do punho e braquiorradial"], "gabarito": "A", "justificativa": "L5 se associa à dorsiflexão e à extensão do hálux; a marcha nos calcanhares testa L5 (slide 11).", "epônimo": null, "tecnica": "L5", "slide": 11}, {"id": 7, "nivel": "muito_dificil", "enunciado": "No teste de Patrick (FABER), qual é a posição do membro e a interpretação de dor posterior reproduzida?", "alternativas": ["Extensão, adução e rotação interna; dor posterior sugere quadril", "Flexão, abdução e rotação externa, com dor sacroilíaca", "Flexão isolada do joelho; dor posterior sugere menisco", "Rotação externa com carga axial; dor posterior sugere tendinite", "Abdução isolada do quadril; dor posterior sugere bursite"], "gabarito": "B", "justificativa": "FABER em '4': flexão, abdução e rotação externa; dor posterior ou sacroilíaca sugere comprometimento sacroilíaco.", "epônimo": null, "tecnica": "Patrick", "slide": 12}, {"id": 8, "nivel": "muito_dificil", "enunciado": "Na manobra de Gaenslen, qual dor é reproduzida e o que ela sugere?", "alternativas": ["Dor glútea lateral, sugerindo tendinite do glúteo médio", "Dor inguinal aguda, sugerindo lesão do ligamento redondo", "Dor posterior habitual, sugerindo disfunção sacroilíaca", "Dor na face lateral do joelho, sugerindo lesão meniscal", "Dor lombar irradiada, sugerindo hérnia no nível L5"], "gabarito": "C", "justificativa": "Gaenslen reproduz a dor posterior habitual, sugerindo disfunção sacroilíaca.", "epônimo": null, "tecnica": "Gaenslen", "slide": 13}, {"id": 9, "nivel": "muito_dificil", "enunciado": "No sinal de Trendelenburg positivo, qual é o déficit funcional e o lado afetado?", "alternativas": ["Lesão do ciático do lado apoiado, com parestesia e dor", "Fraqueza dos flexores do joelho do lado oposto, com dor", "Contratura do psoas ilíaco do lado não apoiado, com dor", "Fraqueza dos abdutores do quadril do lado apoiado", "Fraqueza extensora lombar, com rigidez matinal e dor"], "gabarito": "D", "justificativa": "A queda da pelve do lado não apoiado indica fraqueza dos abdutores do lado apoiado.", "epônimo": null, "tecnica": "Trendelenburg", "slide": 15}, {"id": 10, "nivel": "muito_dificil", "enunciado": "No teste de Thompson, o paciente mantém flexão plantar ativa preservada e anda sem dificuldade. O que se conclui?", "alternativas": ["Tendão do calcâneo íntegro, pois a marcha está preservada", "Teste inválido, pois a flexão ativa dispensa a compressão", "Ruptura excluída, pela preservação da flexão ativa e marcha", "Lesão do nervo tibial, sem relação com o tendão de Aquiles", "Ruptura não excluída, pois a ativa não afasta ruptura"], "gabarito": "E", "justificativa": "Flexão plantar ativa e marcha preservadas não afastam ruptura; o teste de Thompson avalia a flexão plantar à compressão.", "epônimo": null, "tecnica": "Thompson", "slide": 32}, {"id": 11, "nivel": "muito_dificil", "enunciado": "Qual é a posição correta do paciente para o teste de Thompson, segundo a variação entre as fontes?", "alternativas": ["Decúbito ventral ou ajoelhado, com o pé livre da maca", "Decúbito dorsal, com os pés pendentes para fora da maca", "Em pé, com apoio unipodal e marcha na ponta dos pés", "Sentado, com joelho estendido e pé em dorsiflexão", "Decúbito lateral, com abdução do quadril e membro estendido"], "gabarito": "A", "justificativa": "O teste é feito em decúbito ventral ou ajoelhado; Rocco descreve decúbito dorsal, erro corrigido nesta aula.", "epônimo": null, "tecnica": "Thompson", "slide": 47}, {"id": 12, "nivel": "muito_dificil", "enunciado": "Pelas regras de Ottawa, qual achado após trauma do tornozelo indica radiografia?", "alternativas": ["Edema com cacifo na face medial, sem dor óssea à palpação", "Dor óssea em maléolo ou incapacidade de dar 4 passos", "Equimose isolada na planta, sem dor à palpação local", "Dor difusa no dorso sem relação com o trauma recente", "Amplitude de dorsiflexão reduzida, sem dor local ao exame"], "gabarito": "B", "justificativa": "Regras de Ottawa: dor óssea na borda posterior ou ponta dos maléolos (6 cm distais), ou incapacidade de dar 4 passos.", "epônimo": null, "tecnica": "Ottawa", "slide": 41}, {"id": 13, "nivel": "muito_dificil", "enunciado": "No teste de Lachman, em que ângulo de flexão do joelho ele é realizado?", "alternativas": ["Entre 0 e 5 graus, com joelho estendido e relaxado", "Entre 60 e 90 graus, com quadríceps contraído em tensão", "Entre 15 e 30 graus, com isquiotibiais relaxados", "Entre 45 e 60 graus, com rotação interna forçada", "A 120 graus, com joelho em flexão máxima e tensão"], "gabarito": "C", "justificativa": "Lachman é feito com o joelho em leve flexão, cerca de 15 a 30 graus, com isquiotibiais relaxados.", "epônimo": null, "tecnica": "Lachman", "slide": 20}, {"id": 14, "nivel": "muito_dificil", "enunciado": "Ao examinar o reflexo patelar, qual é o nervo responsável pelo arco reflexo?", "alternativas": ["Nervo ciático, pela inervação do quadríceps", "Nervo tibial, pela flexão plantar do pé e dos dedos", "Nervo fibular comum, pela extensão do joelho", "Nervo femoral (L2 a L4), e não o ciático", "Nervo obturador, pela adução do quadril e da coxa"], "gabarito": "D", "justificativa": "O patelar depende do nervo femoral (L2 a L4); atribuí-lo ao ciático é erro de livro-texto corrigido nesta aula.", "epônimo": null, "tecnica": "Erros de livro", "slide": 47}, {"id": 15, "nivel": "muito_dificil", "enunciado": "Monoartrite quente, edemaciada e muito dolorosa, de instalação em horas, com ou sem febre. Qual é a conduta?", "alternativas": ["Analgesia e repouso, com retorno clínico em uma semana", "Observação por quarenta e oito horas sem exame de líquido", "Corticoide intra-articular imediato, sem punção prévia", "Fisioterapia de rotina com exercícios de amplitude articular", "Artrocentese, pois artrite séptica deve ser afastada"], "gabarito": "E", "justificativa": "Articulação quente e muito dolorosa é artrite séptica até prova em contrário: artrocentese com Gram, cultura e cristais.", "epônimo": null, "tecnica": "Sinais de alarme", "slide": 45}], "imagens": [{"slide": 2, "titulo": "Eixo axial: método do exame", "explicacao": "Sequência fixa: inspecionar, palpar, mobilizar e testar. A anamnese orienta o exame físico."}, {"slide": 4, "titulo": "Coluna: inspeção, palpação e mobilidade; teste de Adams", "explicacao": "Inspecione por trás e de perfil. Na flexão anterior, giba persistente = escoliose estrutural."}, {"slide": 5, "titulo": "Teste de Schober", "explicacao": "Marcas A (covinhas de Vênus) e B (10 cm acima). Normal: aumento de 5 cm. Menos de 5 cm = limitação da flexão lombar."}, {"slide": 6, "titulo": "Teste de Spurling", "explicacao": "Inclinação para o lado sintomático com extensão e compressão axial. Positivo: dor irradiada para o membro superior do mesmo lado."}, {"slide": 7, "titulo": "Teste de Lasègue e Lasègue cruzado", "explicacao": "Elevação do membro estendido. Positivo: dor irradiada abaixo do joelho entre cerca de 30° e 70°."}, {"slide": 8, "titulo": "Manobra de Bragard", "explicacao": "Após o Lasègue, abaixe o membro e faça dorsiflexão do pé. Retorno da dor = tensão neural."}, {"slide": 11, "titulo": "Avaliação neurológica das raízes L4, L5 e S1", "explicacao": "Tabela com sensibilidade, força e reflexo de cada raiz. Use para localizar a lesão."}, {"slide": 12, "titulo": "Teste de Patrick (FABER)", "explicacao": "Membro em 4. Dor inguinal = coxofemoral; dor posterior = sacroilíaca."}, {"slide": 13, "titulo": "Teste de Gaenslen", "explicacao": "Flexão de um quadril e hiperextensão do outro na borda da maca. Reproduz dor sacroilíaca."}, {"slide": 14, "titulo": "Rotações do quadril em 90°/90°", "explicacao": "Pé para fora = rotação interna; pé para dentro = rotação externa. Compare com o lado oposto."}, {"slide": 15, "titulo": "Teste de Trendelenburg", "explicacao": "Apoio unipodal: a pelve cai do lado elevado = fraqueza do glúteo médio do lado apoiado."}, {"slide": 16, "titulo": "Teste de Thomas", "explicacao": "Joelho oposto ao tórax com lordose retificada. Coxa testada que se eleva = contratura em flexão."}, {"slide": 17, "titulo": "Joelho: roteiro de inspeção e palpação", "explicacao": "Interlinhas, patela, ligamentos, bolsa anserina e fossa poplítea. Mobilidade normal: flexão 135°."}, {"slide": 18, "titulo": "Sinal da onda", "explicacao": "Derrame pequeno: ordenhe, pressione a face medial e percuta a lateral. A onda reaparece na face medial."}, {"slide": 19, "titulo": "Choque patelar (sinal da tecla)", "explicacao": "Derrame moderado a volumoso: a patela choca contra o fêmur e retorna."}, {"slide": 20, "titulo": "Teste de Lachman", "explicacao": "Teste de escolha para LCA: translação anterior aumentada com parada mole, a 15-30°."}, {"slide": 23, "titulo": "Gaveta anterior", "explicacao": "Joelho a 90°. Observe a queda posterior antes de tracionar para não confundir com LCA."}, {"slide": 24, "titulo": "Gaveta posterior", "explicacao": "Empurrão posterior da tíbia. Deslocamento excessivo sem ponto final firme = lesão do LCP."}, {"slide": 25, "titulo": "Estresse em valgo (LCM)", "explicacao": "Abertura medial = lesão do ligamento colateral medial. Teste em extensão e em 20-30°."}, {"slide": 26, "titulo": "Estresse em varo (LCL)", "explicacao": "Abertura lateral = lesão do ligamento colateral lateral (menos comum)."}, {"slide": 27, "titulo": "Teste de McMurray", "explicacao": "Menisco medial: RE + valgo, estendendo. Menisco lateral: RI, estendendo. Estalido com dor = positivo."}, {"slide": 28, "titulo": "Teste de compressão e distração de Apley", "explicacao": "Compressão avalia meniscos; distração avalia colaterais, com rotação externa (LCM) e interna (LCL)."}, {"slide": 30, "titulo": "Tornozelo: inspeção, palpação e mobilidade", "explicacao": "Maléolos, interlinha tibiotalar, ligamentos e tendão do calcâneo. Mobilidade tibiotalar e subtalar."}, {"slide": 31, "titulo": "Tornozelo: movimentos contra resistência", "explicacao": "Dorsiflexão (tibial anterior, L4-L5), flexão plantar (tríceps sural, S1), inversão e eversão."}, {"slide": 32, "titulo": "Teste de Thompson", "explicacao": "Decúbito ventral, comprimir o tríceps sural. Sem flexão plantar = ruptura do tendão calcâneo."}, {"slide": 38, "titulo": "Mãos: inspeção e palpação dirigidas", "explicacao": "Heberden (IFD) e Bouchard (IFP) na osteoartrite. Sinovite em MCF e punhos sugere artrite inflamatória."}, {"slide": 39, "titulo": "Marchas patológicas", "explicacao": "Ceifante, parkinsoniana, escarvante (pé caído) e anserina (miopática)."}, {"slide": 41, "titulo": "Regras de Ottawa (tornozelo)", "explicacao": "Radiografia se dor em borda ou ponta de maléolo ou incapacidade de dar 4 passos."}, {"slide": 42, "titulo": "Pé: apoio, arcos, antepé e inserções", "explicacao": "Arcos, deformidades (pé plano, cavo, hálux valgo, dedos em martelo) e neuroma de Morton."}, {"slide": 43, "titulo": "Marcha: fase de apoio e balanço", "explicacao": "Apoio ~60% do ciclo, balanço ~40%. Marcha antálgica encurta o apoio do membro doloroso."}, {"slide": 45, "titulo": "Sinais de alarme", "explicacao": "Monoartrite aguda quente: artrocentese urgente. Trauma grave, déficit neurológico e cauda equina são urgências."}], "manobras": [{"nome": "Teste de Adams (flexão anterior do tronco)", "epônimo": "Adams", "como": "Paciente de pé, joelhos estendidos, braços pendentes, flexão do tronco. Examinador observa por trás, tangencialmente ao dorso.", "alterado": "Giba costal ou lombar que persiste na flexão.", "significado": "Escoliose estrutural. Se a giba se corrige na flexão, é escoliose postural.", "slide": 4}, {"nome": "Schober", "epônimo": "Schober", "como": "Marque A na linha média, no nível das covinhas de Vênus, e B 10 cm acima. Peça flexão anterior máxima sem fletir os joelhos e meça A-B.", "alterado": "Aumento menor que 5 cm (A-B menor que 20 cm).", "significado": "Limitação da flexão lombar, como na espondilite anquilosante. Não confirma espondilite isoladamente.", "slide": 5}, {"nome": "Spurling", "epônimo": "Spurling", "como": "Paciente sentado, musculatura cervical relaxada. Examinador atrás: inclina a cabeça para o lado sintomático, estende o pescoço e aplica compressão axial suave no topo da cabeça.", "alterado": "Reprodução de dor ou parestesia irradiada para o membro superior do mesmo lado.", "significado": "Compressão de raiz cervical. Dor cervical local isolada é inespecífica. Não fazer com suspeita de fratura ou instabilidade.", "slide": 6}, {"nome": "Lasègue (elevação do membro estendido)", "epônimo": "Lasègue", "como": "Decúbito dorsal, membro estendido e relaxado. Segure o tornozelo, mantenha o joelho estendido e eleve lentamente. Registre o ângulo de início da dor.", "alterado": "Dor irradiada abaixo do joelho entre cerca de 30 e 70 graus.", "significado": "Tensão de raízes L4 a S1, sobretudo L5 e S1. Dor só na face posterior da coxa indica isquiotibiais, e não é positivo.", "slide": 7}, {"nome": "Lasègue cruzado", "epônimo": "Lasègue", "como": "Eleve o membro sadio, com o paciente em decúbito dorsal.", "alterado": "Reprodução da ciatalgia do lado afetado.", "significado": "Compressão radicular. Pouco sensível, muito específico.", "slide": 7}, {"nome": "Bragard", "epônimo": "Bragard", "como": "Após Lasègue positivo, abaixe o membro 5 a 10 graus, mantenha-o elevado e faça dorsiflexão passiva do pé.", "alterado": "Retorno da dor irradiada.", "significado": "Tensão neural radicular, e não dor muscular.", "slide": 8}, {"nome": "Patrick (FABER)", "epônimo": "Patrick", "como": "Decúbito dorsal. Membro em posição de 4, maléolo lateral sobre a coxa contralateral. Uma mão estabiliza a espinha ilíaca; a outra pressiona o joelho em direção à maca.", "alterado": "Dor inguinal ou dor posterior sacroilíaca reproduzida.", "significado": "Dor inguinal: coxofemoral. Dor posterior: sacroilíaca. É teste de provocação e não define diagnóstico sozinho.", "slide": 12}, {"nome": "Gaenslen", "epônimo": "Gaenslen", "como": "Paciente em decúbito dorsal, com a nádega do lado testado na borda da maca. Flexione o quadril contralateral ao máximo e deixe o membro testado pendente, pressionando em hiperextensão.", "alterado": "Reprodução da dor posterior habitual na região sacroilíaca.", "significado": "Dor sacroilíaca. Não comprova sacroiliíte isoladamente.", "slide": 13}, {"nome": "Rotação do quadril em 90 graus", "epônimo": null, "como": "Decúbito dorsal, quadril e joelho a 90 graus. Uma mão estabiliza o joelho; a outra conduz o tornozelo para dentro (rotação interna) e para fora (rotação externa).", "alterado": "Limitação de amplitude, sobretudo da rotação interna, comparada ao lado oposto.", "significado": "Artrose coxofemoral (rotação interna é a primeira a limitar). Dor inguinal sugere origem intra-articular; dor lateral com trocânter, periarticular.", "slide": 14}, {"nome": "Trendelenburg", "epônimo": "Trendelenburg", "como": "Paciente em pé, examinador atrás observando as cristas ilíacas. Apoio unipodal por cerca de 30 segundos, depois o outro lado.", "alterado": "Queda da pelve do lado do pé elevado.", "significado": "Fraqueza dos abdutores do quadril (glúteo médio) do lado apoiado. Na marcha gera a marcha de Trendelenburg.", "slide": 15}, {"nome": "Thomas", "epônimo": "Thomas", "como": "Decúbito dorsal. O paciente abraça o joelho oposto e o leva ao tórax até retificar a lordose lombar; observe a coxa testada.", "alterado": "A coxa testada se eleva da maca.", "significado": "Contratura em flexão do quadril (iliopsoas ou reto femoral). Sem retificar a lordose, pode haver falso-negativo.", "slide": 16}, {"nome": "Sinal da onda", "epônimo": null, "como": "Joelho estendido, quadríceps relaxado. Ordenhe o recesso suprapatelar; pressione a face medial; percuta ou deslize a face lateral.", "alterado": "Onda de líquido que reaparece na face medial.", "significado": "Derrame pequeno. Nos derrames volumosos e tensos pode não aparecer.", "slide": 18}, {"nome": "Choque patelar (sinal da tecla)", "epônimo": null, "como": "Decúbito dorsal, joelho estendido e quadríceps relaxado. Comprima o recesso suprapatelar e empurre a patela contra o fêmur com movimento rápido.", "alterado": "A patela desce, choca contra o fêmur e retorna.", "significado": "Derrame moderado a volumoso. Falso-negativo com derrame pequeno ou muito tenso.", "slide": 19}, {"nome": "Lachman", "epônimo": "Lachman", "como": "Joelho a 15 a 30 graus, isquiotibiais relaxados. Estabilize o fêmur distal e trace a tíbia proximal para frente.", "alterado": "Translação anterior maior que a do lado oposto, com parada mole.", "significado": "Lesão do LCA. Teste de escolha. Defesa dos isquiotibiais gera falso-negativo.", "slide": 20}, {"nome": "Gaveta anterior", "epônimo": null, "como": "Quadril a 45 graus, joelho a 90 graus, pé estabilizado. Trace a tíbia para frente. Antes, observe o sinal da queda posterior.", "alterado": "Deslizamento anterior excessivo sem ponto final firme.", "significado": "Lesão do LCA. Se a tíbia já estava caída para trás, o achado é falso-positivo e sugere LCP.", "slide": 23}, {"nome": "Gaveta posterior (sinal da queda posterior)", "epônimo": null, "como": "Mesma posição da gaveta anterior. Observe a tíbia de perfil e empurre a tíbia proximal para trás.", "alterado": "Tíbia caída para trás ou deslocamento posterior excessivo sem ponto final.", "significado": "Lesão do LCP.", "slide": 24}, {"nome": "Estresse em valgo", "epônimo": null, "como": "Decúbito dorsal, coxa levemente abduzida. Uma mão empurra o joelho para medial e a outra puxa o tornozelo para lateral. Teste em extensão e em 20 a 30 graus.", "alterado": "Abertura medial excessiva sem ponto final firme, ou dor na interlinha medial.", "significado": "Lesão do LCM. Abertura em extensão sugere lesão associada.", "slide": 25}, {"nome": "Estresse em varo", "epônimo": null, "como": "Mesma posição do valgo, com as mãos invertidas.", "alterado": "Abertura lateral excessiva sem ponto final firme.", "significado": "Lesão do LCL (menos comum que a do LCM).", "slide": 26}, {"nome": "McMurray", "epônimo": "McMurray", "como": "Decúbito dorsal. Segure o calcanhar e leve o joelho à flexão máxima; palpe as interlinhas. Menisco medial: rotação externa com valgo, estendendo. Menisco lateral: rotação interna com varo, estendendo.", "alterado": "Estalido palpável com dor durante a extensão.", "significado": "Lesão meniscal no compartimento testado. Estalido indolor isolado é inespecífico.", "slide": 27}, {"nome": "Apley (compressão e distração)", "epônimo": "Apley", "como": "Decúbito ventral, joelho a 90 graus. Compressão com rotação da tíbia; distração com tração da perna para cima e repetição das rotações.", "alterado": "Dor ou estalido na compressão; dor na distração.", "significado": "Compressão: meniscos (rotação externa, medial; rotação interna, lateral). Distração: colaterais (rotação externa, LCM; rotação interna, LCL).", "slide": 28}, {"nome": "Força contra resistência (tornozelo)", "epônimo": null, "como": "Estabilize a perna. Resista à dorsiflexão, à flexão plantar, à inversão e à eversão, graduando de 0 a 5.", "alterado": "Dor com força preservada no passivo, ou fraqueza indolor.", "significado": "Dor aguda inibe o esforço e simula paresia. Fraqueza indolor sugere causa neurológica.", "slide": 31}, {"nome": "Thompson", "epônimo": "Thompson", "como": "Decúbito ventral, joelho e tornozelo a 90 graus (ou ajoelhado). Comprima o ventre do tríceps sural e observe a flexão plantar.", "alterado": "Ausência de flexão plantar à compressão.", "significado": "Ruptura do tendão do calcâneo. Flexão plantar ativa preservada não afasta ruptura. Sinônimos: Simmonds e Thompson-Doherty.", "slide": 32}, {"nome": "Compressão lateral das MCF", "epônimo": null, "como": "Comprima lateralmente as metacarpofalângicas, com as mãos relaxadas.", "alterado": "Dor localizada nas MCF.", "significado": "Triagem de sinovite (ex.: AR). Não é diagnóstico.", "slide": 38}, {"nome": "Observação da marcha", "epônimo": null, "como": "Observe entrada, retorno, mudança de direção e base de apoio, com o paciente caminhando.", "alterado": "Encurtamento do apoio de um lado, queda da pelve, passos curtos, pé caído, oscilação bilateral.", "significado": "Antálgica (encurta o apoio doloroso); Trendelenburg (pelve); parkinsoniana (passos curtos); escarvante (pé caído, L5 ou fibular); anserina (miopatia, fraqueza bilateral).", "slide": 39}, {"nome": "Regras de Ottawa (tornozelo e pé)", "epônimo": null, "como": "Palpe a borda posterior e a ponta dos maléolos, a base do quinto metatarso e o navicular. Verifique se a pessoa dá 4 passos.", "alterado": "Dor à palpação em qualquer desses pontos, ou incapacidade de dar 4 passos.", "significado": "Indica radiografia após trauma de tornozelo ou pé.", "slide": 41}], "casos_extremos": [{"titulo": "Caso V1 · Lombociatalgia com sinais dissociados", "texto": "Homem de 39 anos, motorista, refere dor lombar e ciatalgia direita há 3 semanas. Lasègue positivo a 40 graus com dor abaixo do joelho. Bragard positivo após abaixar 8 graus e fazer dorsiflexão passiva. Reflexo patelar normal, aquileu diminuído à direita. Força de dorsiflexão 5/5, extensão do hálux 5/5, flexão plantar 4/5 à direita.", "perguntas": [{"pergunta": "Qual raiz é mais provável, considerando os reflexos e a força?", "alternativas": ["L4, pelo reflexo patelar normal e pela força preservada", "S1, pelo reflexo aquileu diminuído e fraqueza na flexão plantar", "L5, pela extensão do hálux preservada e pela dorsiflexão normal", "C6, pelo Lasègue positivo e pela dor irradiada", "L2, pela ciatalgia com dor irradiada ao quadril"], "gabarito": "B", "justificativa": "Reflexo aquileu diminuído e fraqueza de flexão plantar apontam S1; L5 não tem reflexo confiável e o hálux estava preservado."}, {"pergunta": "Qual é o significado clínico do Bragard positivo nesta apresentação?", "alternativas": ["Tensão isolada da musculatura isquiotibial, sem origem neural", "Sensibilização da tensão neural radicular, com dor que retorna com dorsiflexão", "Artrite do quadril, pela dor com mobilização passiva do membro", "Lesão meniscal, pela dor ao estender o joelho com força", "Doença vascular periférica, pela dor à dorsiflexão do pé"], "gabarito": "B", "justificativa": "Bragard é positivo quando a dorsiflexão com o membro elevado reproduz a dor irradiada, indicando tensão neural radicular."}]}, {"titulo": "Caso V2 · Ruptura do tendão de Aquiles disfarçada", "texto": "Homem de 45 anos, praticante de futebol, relata estalo na panturrilha esquerda há 2 dias, seguido de dor. Consegue caminhar com dificuldade. Flexão plantar ativa preservada em 4/5. Thompson com flexão plantar parcial à compressão do ventre da panturrilha. Há palpação de falha no trajeto do tendão.", "perguntas": [{"pergunta": "Qual é a interpretação mais adequada do Thompson e da flexão plantar ativa?", "alternativas": ["Tendão íntegro, pela flexão plantar ativa preservada", "Ruptura não excluída, pois a flexão ativa não afasta ruptura e há falha", "Ruptura excluída, pela marcha possível sem apoio de muletas", "Lesão do nervo tibial, sem relação com o tendão de Aquiles", "Tendinite crônica sem ruptura, com dor à palpação do tendão"], "gabarito": "B", "justificativa": "Flexão ativa preservada não afasta ruptura; a falha palpável no trajeto e a flexão plantar parcial à compressão sustentam a hipótese."}, {"pergunta": "Qual é a posição correta do paciente para o teste de Thompson realizado neste caso?", "alternativas": ["Decúbito dorsal com os pés pendentes para fora da maca", "Decúbito ventral ou ajoelhado, com o pé livre da maca", "Em pé, com apoio unipodal e marcha na ponta dos pés", "Sentado com joelho estendido e pé em dorsiflexão ativa", "Decúbito lateral com abdução do quadril e membro estendido"], "gabarito": "B", "justificativa": "O teste é realizado em decúbito ventral ou ajoelhado; a descrição em decúbito dorsal, presente em alguns livros, é erro."}]}, {"titulo": "Caso V3 · Marcha claudicante e quadril", "texto": "Mulher de 60 anos, com osteoartrose de quadril direito, apresenta marcha claudicante. Trendelenburg positivo à direita, com queda da pelve do lado esquerdo ao apoio unipodal direito. Teste de Thomas positivo: coxa direita se eleva do plano da maca. Dor inguinal ao FABER à direita.", "perguntas": [{"pergunta": "Qual é a interpretação do Trendelenburg positivo à direita?", "alternativas": ["Fraqueza dos abdutores do quadril direito, do lado apoiado", "Fraqueza dos abdutores do quadril esquerdo, do lado não apoiado", "Contratura do psoas esquerdo, com dor à extensão do quadril", "Lesão do nervo ciático direito, com parestesia lateral da coxa", "Fraqueza do quadríceps esquerdo, com perda de extensão do joelho"], "gabarito": "A", "justificativa": "A queda da pelve do lado não apoiado indica fraqueza dos abdutores do quadril do lado apoiado, que é o direito."}, {"pergunta": "Qual é a interpretação do Thomas positivo nesta paciente?", "alternativas": ["Contratura em flexão do quadril direito, compatível com artrose", "Fraqueza do glúteo máximo esquerdo, com perda de extensão", "Ruptura do ligamento redondo esquerdo, com dor inguinal", "Bursite trocantérica esquerda, com dor à palpação lateral", "Fratura do colo femoral esquerdo, com encurtamento do membro"], "gabarito": "A", "justificativa": "A coxa que se eleva no Thomas indica contratura em flexão do quadril do lado examinado, coerente com a artrose direita."}]}]};
